INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('faf61d35-93c5-564e-aba5-0fa4818aa3fe', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 7, 7, 'Which is an assumption of the kinetic model of an ideal gas?', NULL, 1, 'multiple_choice'::answer_type, 'The molecules have negligible volume compared with the volume of the container', NULL, false, NULL, false, NULL, 'The ideal-gas model assumes point-like molecules, no forces except in collisions, elastic collisions and random motion. Mark scheme (1 mark). B1: C (The molecules have negligible volume compared with the volume of the container).', 1),
('f740ee54-a8a2-5a6c-bc13-d6940ad66ff5', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 8, 8, 'Smoke particles in air, viewed through a microscope, move in a jerky, random way. What is this called?', NULL, 1, 'multiple_choice'::answer_type, 'Brownian motion', NULL, false, NULL, false, NULL, 'The visible smoke particles are bombarded unevenly by unseen, fast-moving air molecules: evidence for molecular motion. Mark scheme (1 mark). B1: A (Brownian motion).', 1),
('3faf2fd2-0624-51da-bd49-a26e5d5b5f33', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 9, 9, 'What causes the random zig-zag motion of a smoke particle in Brownian motion?', NULL, 1, 'multiple_choice'::answer_type, 'Uneven bombardment by much smaller, fast-moving air molecules', NULL, false, NULL, false, NULL, 'At any instant more molecules hit one side than the other, so the particle is pushed in a random direction. Mark scheme (1 mark). B1: D (Uneven bombardment by much smaller, fast-moving air molecules).', 1),
('9cfee3c8-81c7-56e0-b772-432ec6c28006', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 10, 10, 'How many molecules are there in 0.50 mol of carbon dioxide? Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '3.01e23', NULL, false, NULL, false, NULL, 'N = nN_A = 0.50 × 6.02 × 10²³ = 3.01 × 10²³. Mark scheme (2 marks). C1: N = nN_A. A1: N = 3.01 × 10²³.', 2),
('777f0e30-4c8b-5ec7-babc-31e825b12d72', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 11, 11, 'A cylinder contains 9.0 × 10²⁴ molecules of nitrogen. How many moles is this? Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '14.95', 'mol', false, NULL, false, NULL, 'n = N/N_A = 9.0 × 10²⁴ ÷ 6.02 × 10²³ = 15.0 mol. Mark scheme (2 marks). C1: n = N/N_A. A1: n = 15.0 mol.', 2),
('480364fe-19ad-5068-bfb5-eb51af0b2ea4', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 12, 12, 'Why is it reasonable to ignore the forces between molecules in a gas at low pressure?', NULL, 1, 'multiple_choice'::answer_type, 'The molecules are far apart on average, so the forces are negligible except during collisions', NULL, false, NULL, false, NULL, 'Intermolecular forces act only over short ranges; in a dilute gas the molecules spend most of their time far apart. Mark scheme (1 mark). B1: B (The molecules are far apart on average, so the forces are negligible except during collisions).', 1),
('da80ccf9-033b-5a8b-8263-ef071ec64e16', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 13, 13, 'In the kinetic model, how do gas molecules move between collisions?', NULL, 1, 'multiple_choice'::answer_type, 'In straight lines at constant speed', NULL, false, NULL, false, NULL, 'With no forces between collisions, each molecule moves in a straight line at constant velocity. Mark scheme (1 mark). B1: C (In straight lines at constant speed).', 1),
('1dfa4f72-5768-5ce7-b17d-092f45b944f7', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 14, 14, 'Calculate the mass of 3.5 mol of oxygen gas, molar mass 0.032 kg mol⁻¹.', NULL, 1, 'numeric'::answer_type, '0.112', 'kg', false, NULL, false, NULL, 'm = nM = 3.5 × 0.032 = 0.112 kg. Mark scheme (2 marks). C1: m = nM. A1: m = 0.112 kg.', 2),
('3272c4a0-c642-59d3-90b0-f256622c2030', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 15, 15, 'Why does a gas fill any container it is placed in?', NULL, 1, 'multiple_choice'::answer_type, 'Its molecules move randomly in all directions with little attraction between them', NULL, false, NULL, false, NULL, 'Random, nearly free motion spreads the molecules through the whole available volume. Mark scheme (1 mark). B1: A (Its molecules move randomly in all directions with little attraction between them).', 1),
('18688f85-1367-5a8c-a94d-cbdcfb416d89', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 16, 16, 'A balloon contains 0.20 mol of helium (molar mass 4.0 g mol⁻¹). Calculate the mass of the helium in kg.', NULL, 1, 'numeric'::answer_type, '8e-4', 'kg', false, NULL, false, NULL, 'm = nM = 0.20 × 0.0040 = 8.0 × 10⁻⁴ kg. Mark scheme (2 marks). C1: molar mass in kg mol⁻¹. A1: m = 8.0 × 10⁻⁴ kg.', 2),
('03fb52d2-9c75-5483-be80-2dc54c38b322', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 17, 17, 'Which observation supports the idea that gas molecules are in constant random motion?', NULL, 1, 'multiple_choice'::answer_type, 'A smell spreading across a room even with no draughts', NULL, false, NULL, false, NULL, 'Diffusion of the scent molecules through the air shows random molecular motion. Mark scheme (1 mark). B1: D (A smell spreading across a room even with no draughts).', 1),
('4546c04c-6055-5e86-803e-2d6e21a85fbf', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 18, 18, 'A room contains 2.5 × 10²⁷ air molecules. How many moles of air is this? Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '4153', 'mol', false, NULL, false, NULL, 'n = N/N_A = 2.5 × 10²⁷ ÷ 6.02 × 10²³ = 4150 mol. Mark scheme (2 marks). C1: n = N/N_A. A1: n = 4150 mol.', 2),
('46f74498-057d-5566-88f0-9f913c1fa576', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 19, 19, 'What is meant by the statement that collisions between ideal-gas molecules are elastic?', NULL, 1, 'multiple_choice'::answer_type, 'Total kinetic energy is conserved in each collision', NULL, false, NULL, false, NULL, 'In an elastic collision no kinetic energy is converted to other forms. Mark scheme (1 mark). B1: B (Total kinetic energy is conserved in each collision).', 1),
('0eca563a-266f-59a0-bf16-4cb2846591e0', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 20, 20, 'Why do the smoke particles in a Brownian-motion experiment move more vigorously when the air is warmer?', NULL, 1, 'multiple_choice'::answer_type, 'The air molecules move faster, so their impacts are harder and more frequent', NULL, false, NULL, false, NULL, 'Higher temperature means a higher mean molecular kinetic energy. Mark scheme (1 mark). B1: C (The air molecules move faster, so their impacts are harder and more frequent).', 1),
('d58487e6-6077-55fc-955d-8d91b8785941', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 21, 21, 'Calculate the number of molecules in 18 g of water (molar mass 18 g mol⁻¹). Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '6.02e23', NULL, false, NULL, false, NULL, 'n = 18 ÷ 18 = 1.0 mol, so N = 1.0 × 6.02 × 10²³ = 6.02 × 10²³. Mark scheme (2 marks). C1: n = m/M then N = nN_A. A1: N = 6.02 × 10²³.', 2),
('69781439-6cec-59bc-a64d-6727a51450b0', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 22, 22, 'Which of these is NOT an assumption of the kinetic theory of an ideal gas?', NULL, 1, 'multiple_choice'::answer_type, 'All the molecules move at the same speed', NULL, false, NULL, false, NULL, 'Molecules have a range of speeds; only the distribution is fixed by the temperature. Mark scheme (1 mark). B1: A (All the molecules move at the same speed).', 1),
('3561320d-69b5-57f6-9711-f6d1f3f41de1', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 23, 23, 'Calculate the mass of one nitrogen molecule (molar mass 0.028 kg mol⁻¹). Give your answer in units of 10⁻²⁶ kg. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '4.651', '10⁻²⁶ kg', false, NULL, false, NULL, 'm = M/N_A = 0.028 ÷ 6.02 × 10²³ = 4.65 × 10⁻²⁶ kg. Mark scheme (3 marks). C1: m = M/N_A. C1: molar mass in kg. A1: m = 4.65 × 10⁻²⁶ kg.', 3),
('b6668506-21d0-5e4c-a43f-35b8875972be', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 24, 24, 'At room conditions a gas has 2.5 × 10²⁵ molecules per m³. Estimate the average spacing between molecules, assuming each occupies a small cube. Give your answer in nm.', NULL, 2, 'numeric'::answer_type, '3.42 nm', 'nm', false, NULL, false, NULL, 'Volume per molecule = 1 ÷ 2.5 × 10²⁵ = 4.0 × 10⁻²⁶ m³. Spacing = (4.0 × 10⁻²⁶)^(1/3) = 3.42 × 10⁻⁹ m. In nm: 3.420 × 10⁻⁹ × 10⁹ = 3.42. Mark scheme (3 marks). C1: volume per molecule. C1: cube root. C1: convert.', 3),
('f17ade8e-d626-5393-b799-2ba7af8696db', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 25, 25, 'A molecule has a diameter of about 0.3 nm and the mean spacing in air is about 3 nm. Which assumption of the kinetic theory does this support?', NULL, 2, 'multiple_choice'::answer_type, 'The volume of the molecules is negligible compared with the volume of the gas', NULL, false, NULL, false, NULL, 'Spacing ≈ 10 × diameter means the molecules occupy only about 1/1000 of the volume. Mark scheme (3 marks). C1: compare sizes. C1: negligible volume. A1: D (The volume of the molecules is negligible compared with the volume of the gas).', 3),
('4b6138fc-910d-52ae-9dec-b780b0afd555', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 26, 26, 'A sealed flask of volume 2.0 × 10⁻³ m³ contains 0.090 mol of air. Calculate the number of molecules per cubic metre. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '2.709e25', 'm⁻³', false, NULL, false, NULL, 'N = 0.090 × 6.02 × 10²³ = 5.42 × 10²². N/V = 5.418 × 10²² ÷ 2.0 × 10⁻³ = 2.71 × 10²⁵ m⁻³. Mark scheme (3 marks). C1: N = nN_A. C1: ÷ V. A1: n = 2.71 × 10²⁵ m⁻³.', 3),
('f3c972fb-8efe-53f7-97ea-09226c49eca0', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 27, 27, 'A helium atom has mass 6.6 × 10⁻²⁷ kg. Calculate the number of atoms in 1.0 g of helium, and hence estimate the Avogadro constant from the molar mass 4.0 g mol⁻¹. Give your estimate of the Avogadro constant.', NULL, 2, 'numeric'::answer_type, '6.061e23', 'mol⁻¹', false, NULL, false, NULL, 'Atoms in 1.0 g = 1.0 × 10⁻³ ÷ 6.6 × 10⁻²⁷ = 1.52 × 10²³. In 4.0 g (one mole): 4.0 × 10⁻³ ÷ 6.6 × 10⁻²⁷ = 6.06 × 10²³. Mark scheme (4 marks). C1: N = m/m_atom. C1: one mole = 4.0 g. C1: substitution. A1: N_A = 6.06 × 10²³ mol⁻¹.', 4),
('5ac5bcba-6e88-5abb-85cf-033bf9a50b6b', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 28, 28, 'In Brownian motion, why are larger smoke particles seen to move less than smaller ones?', NULL, 2, 'multiple_choice'::answer_type, 'The random imbalance of impacts is smaller relative to their larger mass and size', NULL, false, NULL, false, NULL, 'A larger particle receives more impacts, so they average out better, and its larger mass gives a smaller acceleration. Mark scheme (3 marks). C1: impacts average out. C1: larger inertia. A1: B (The random imbalance of impacts is smaller relative to their larger mass and size).', 3),
('8cb9f9c6-bedc-55cd-a39e-904f5fecd97c', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 29, 29, 'A gas cylinder contains 4.0 kg of propane (molar mass 0.044 kg mol⁻¹). Calculate the number of molecules. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '5.473e25', NULL, false, NULL, false, NULL, 'n = m/M = 4.0 ÷ 0.044 = 90.9 mol. N = nN_A = 90.91 × 6.02 × 10²³ = 5.47 × 10²⁵. Mark scheme (3 marks). C1: n = m/M. C1: N = nN_A. A1: N = 5.47 × 10²⁵.', 3),
('15e4252f-7f67-5c37-9023-efd8014f4678', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 30, 30, 'Why is the duration of a molecular collision assumed to be much less than the time between collisions?', NULL, 2, 'multiple_choice'::answer_type, 'So that at any instant almost all molecules are moving freely, and forces act only during brief impacts', NULL, false, NULL, false, NULL, 'If collisions were long, the molecules would spend significant time interacting, and the simple model (free straight-line motion) would fail. Mark scheme (4 marks). C1: free motion most of the time. C1: forces only briefly. C1: simplifies the model. A1: C (So that at any instant almost all molecules are moving freely, and forces act only during brief impacts).', 4),
('6d1846ca-4a10-50c5-9a6c-c8ec30615c29', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 31, 31, 'A scuba tank holds 2.4 × 10²⁶ molecules of air (mean molar mass 0.029 kg mol⁻¹). Calculate the mass of air in the tank. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '11.56', 'kg', false, NULL, false, NULL, 'n = 2.4 × 10²⁶ ÷ 6.02 × 10²³ = 399 mol. m = nM = 398.7 × 0.029 = 11.6 kg. Mark scheme (3 marks). C1: n = N/N_A. C1: m = nM. A1: m = 11.6 kg.', 3),
('a02679b3-df2c-5de4-8f3c-84874353fa25', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 32, 32, 'A gas is compressed so its molecules are closer together. Which kinetic-theory assumption becomes less valid?', NULL, 2, 'multiple_choice'::answer_type, 'That the molecules'' own volume and the forces between them are negligible', NULL, false, NULL, false, NULL, 'At high density the molecules occupy a larger fraction of the volume and are close enough to attract each other. Mark scheme (3 marks). C1: volume of molecules. C1: intermolecular forces. A1: A (That the molecules'' own volume and the forces between them are negligible).', 3),
('8c7c7330-a94a-54d4-a404-b7d75b2d80e4', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 33, 33, 'Estimate the diameter of an argon atom, assuming that in liquid argon (density 1400 kg m⁻³, molar mass 0.040 kg mol⁻¹) the atoms are packed in cubes. Give your answer in nm. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '0.3621 nm', 'nm', false, NULL, false, NULL, 'Volume per atom = M/(ρN_A) = 0.040 ÷ (1400 × 6.02 × 10²³) = 4.75 × 10⁻²⁹ m³. d = (4.746 × 10⁻²⁹)^(1/3) = 3.62 × 10⁻¹⁰ m. In nm: 3.621 × 10⁻¹⁰ × 10⁹ = 0.362. Mark scheme (4 marks). C1: volume per atom. C1: cube root. C1: convert to nm. A1: d = 0.362 nm.', 4),
('9e99e8ed-0adc-56a0-8893-914c91621f4f', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 34, 34, 'Which statement about the speeds of molecules in a gas at constant temperature is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The molecules have a wide range of speeds, but the distribution stays the same over time', NULL, false, NULL, false, NULL, 'Collisions constantly exchange energy, but the overall distribution is steady at a given temperature. Mark scheme (3 marks). C1: range of speeds. C1: steady distribution. A1: D (The molecules have a wide range of speeds, but the distribution stays the same over time).', 3),
('1d52aa52-e883-5392-bc81-5684573cbd8d', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 35, 35, 'A droplet of mercury contains 3.0 × 10¹⁸ atoms. Mercury has molar mass 0.201 kg mol⁻¹. Calculate the mass of the droplet in mg. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '1.002 mg', 'mg', false, NULL, false, NULL, 'n = 3.0 × 10¹⁸ ÷ 6.02 × 10²³ = 4.98 × 10⁻⁶ mol. m = nM = 4.983 × 10⁻⁶ × 0.201 = 1.00 × 10⁻⁶ kg. In mg: 1.002 × 10⁻⁶ × 10⁶ = 1.00. Mark scheme (3 marks). C1: n = N/N_A. C1: m = nM. C1: convert.', 3),
('d0e42edb-8e88-55ec-a583-c309b2031044', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 36, 36, 'A student argues: "Gas molecules must slow down when they hit the walls, so the gas gradually cools." Which is the correct response?', NULL, 2, 'multiple_choice'::answer_type, 'For an ideal gas the collisions are elastic: the molecules rebound with the same speed, so no kinetic energy is lost', NULL, false, NULL, false, NULL, 'Elastic collisions conserve kinetic energy; a gas in equilibrium with its container does not cool. Mark scheme (3 marks). C1: elastic collisions. C1: no loss of kinetic energy. A1: B (For an ideal gas the collisions are elastic: the molecules rebound with the same speed, so no kinetic energy is lost).', 3),
('4f804ad2-9104-5078-8fcd-5be11f1c1b28', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 37, 37, 'A container of volume 0.025 m³ holds nitrogen (molar mass 0.028 kg mol⁻¹) of density 1.2 kg m⁻³. Calculate the number of molecules. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '6.45e23', NULL, false, NULL, false, NULL, 'm = ρV = 1.2 × 0.025 = 0.030 kg. n = 0.030 ÷ 0.028 = 1.07 mol. N = 1.071 × 6.02 × 10²³ = 6.45 × 10²³. Mark scheme (4 marks). C1: m = ρV. C1: n = m/M. C1: N = nN_A. A1: N = 6.45 × 10²³.', 4),
('c74977bf-6ab5-5770-bd52-bcc23257b91a', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 38, 38, 'Why is it reasonable to treat gas molecules as "point particles" when explaining pressure?', NULL, 2, 'multiple_choice'::answer_type, 'Their size is tiny compared with the distances they travel between collisions', NULL, false, NULL, false, NULL, 'Pressure comes from momentum transfer at the walls; the molecules'' sizes barely matter when they are so far apart. Mark scheme (3 marks). C1: size vs spacing. C1: negligible. A1: C (Their size is tiny compared with the distances they travel between collisions).', 3),
('4bb047b0-0dbd-5a5c-a09e-c7422a33aee1', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 39, 39, 'A sample of xenon (molar mass 0.131 kg mol⁻¹) has a mass of 0.65 kg. Calculate the number of moles and the number of atoms. Give the number of atoms. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '2.987e24', NULL, false, NULL, false, NULL, 'n = 0.65 ÷ 0.131 = 4.96 mol. N = 4.962 × 6.02 × 10²³ = 2.99 × 10²⁴. Mark scheme (3 marks). C1: n = m/M. C1: N = nN_A. A1: N = 2.99 × 10²⁴.', 3),
('3bcf09f7-b9ff-54c0-a986-1842637a7f8e', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 40, 40, 'A person breathes in 0.50 litres of air. Under room conditions one mole of any gas occupies about 0.024 m³. Estimate the number of molecules taken in with each breath. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '1.254e22', NULL, false, NULL, false, NULL, 'V = 0.50 litres = 5.0 × 10⁻⁴ m³. n = 5.0 × 10⁻⁴ ÷ 0.024 = 0.0208 mol. N = 0.02083 × 6.02 × 10²³ = 1.25 × 10²². Mark scheme (3 marks). C1: litres converted to m³. C1: n = V/V_m. A1: N = 1.25 × 10²².', 3),
('77c3f7ba-c43b-5d19-bda3-39526cfa8480', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 41, 41, 'Air at room temperature has a density of 1.2 kg m⁻³ and a mean molar mass of 0.029 kg mol⁻¹. (a) Calculate the number of molecules per m³. (b) Estimate the mean spacing between molecules. (c) A molecule has diameter 3.5 × 10⁻¹⁰ m. Estimate the fraction of the volume occupied by the molecules themselves. Give only the answer to (b), in nm. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '3.424 nm', 'nm', false, NULL, false, NULL, '(a) n = 1.2 ÷ 0.029 × 6.02 × 10²³ = 2.49 × 10²⁵ m⁻³. (b) spacing = (1 ÷ 2.491 × 10²⁵)^(1/3) = 3.42 × 10⁻⁹ m. In nm: 3.424 × 10⁻⁹ × 10⁹ = 3.42. (c) fraction ≈ n × (π/6)d³ ≈ 5.59 × 10⁻⁴: about 0.06 %. Mark scheme (5 marks). C1: number density. A1: n. C1: cube root of volume per molecule. A1: d = 3.42 nm. B1: fraction small.', 5),
('18ac6ed2-594d-5c47-be5a-dbdd451159a8', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 42, 42, 'A Brownian-motion experiment uses smoke particles of mass 1.0 × 10⁻¹⁶ kg in air at 300 K. Each particle has the same mean kinetic energy as an air molecule, (3/2)kT. (a) Calculate this mean kinetic energy, in units of 10⁻²¹ J. (b) Calculate the root-mean-square speed of a smoke particle. (c) Explain why the smoke particle moves so much more slowly than an air molecule (rms speed about 500 m s⁻¹). Give only the answer to (b), in mm s⁻¹. Take k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 3, 'numeric'::answer_type, '11.14', 'mm s⁻¹', false, NULL, false, NULL, '(a) ⟨Ek⟩ = 1.5 × 1.38 × 10⁻²³ × 300 = 6.21 × 10⁻²¹ J = 6.21 × 10⁻²¹ J. (b) c_rms = √(3kT/m) = √(3 × 1.38 × 10⁻²³ × 300 ÷ 1.0 × 10⁻¹⁶) = 0.0111 m s⁻¹. In mm s⁻¹: 0.01114 × 1000 = 11.1. (c) Same kinetic energy but about 10¹⁰ times the mass, so a speed about 10⁵ times smaller. Mark scheme (6 marks). C1: (3/2)kT. A1: energy. C1: c_rms = √(3kT/m). A1: c_rms = 11.1 mm s⁻¹. B1: much larger mass. B1: same mean Ek.', 6),
('223382b9-a83a-5170-bcc0-fa587bea3146', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 43, 43, 'A cylinder of volume 0.050 m³ contains 2.4 mol of an ideal gas. (a) Calculate the number of molecules. (b) Calculate the number density. (c) The volume is halved at constant temperature. State and explain the effect on the rate at which molecules hit each square metre of wall. Give only the answer to (b). Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '2.89e25', 'm⁻³', false, NULL, false, NULL, '(a) N = 2.4 × 6.02 × 10²³ = 1.44 × 10²⁴. (b) n = N/V = 1.445 × 10²⁴ ÷ 0.050 = 2.89 × 10²⁵ m⁻³. (c) The number density doubles at the same molecular speeds, so the rate of collisions per m² doubles (and so does the pressure). Mark scheme (5 marks). A1: N. C1: n = N/V. A1: n = 2.89 × 10²⁵ m⁻³. B1: rate doubles. B1: same speed, twice density.', 5),
('f5e0be44-78c4-50b8-899e-1938dc3263f7', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 44, 44, 'A diver''s lungs hold 6.0 litres of air at the surface (1.0 × 10⁵ Pa, 300 K), containing about 0.24 mol. (a) Calculate the number of molecules. (b) The air is 21 % oxygen by number. Calculate the mass of oxygen (molar mass 0.032 kg mol⁻¹). (c) At 20 m depth the pressure is 3.0 × 10⁵ Pa. Explain, in terms of molecules, why the same lung volume now holds three times as much air. Give only the answer to (b). Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '0.001613', 'kg', false, NULL, false, NULL, '(a) N = 0.24 × 6.02 × 10²³ = 1.44 × 10²³. (b) n(O₂) = 0.21 × 0.24 = 0.0504 mol, m = 0.05040 × 0.032 = 0.00161 kg. (c) Three times the pressure at the same temperature needs three times the number of molecules per unit volume hitting the walls with the same mean speed. Mark scheme (6 marks). A1: N. C1: moles of O₂. C1: m = nM. A1: m = 0.00161 kg. B1: n ∝ p at same T. B1: molecular explanation.', 6),
('d566f3f9-fc65-515d-b6ae-1c302b1acbe7', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 45, 45, 'Interstellar space contains about 1.0 × 10⁶ hydrogen atoms per m³ at about 100 K. (a) Calculate the mass of hydrogen in 1.0 m³ (atom mass 1.67 × 10⁻²⁷ kg), in units of 10⁻²¹ kg. (b) Estimate the mean spacing between atoms. (c) Explain why the gas still exerts a pressure. Give only the answer to (b), in mm.', NULL, 3, 'numeric'::answer_type, '10 mm', 'mm', false, NULL, false, NULL, '(a) m = 1.0 × 10⁶ × 1.67 × 10⁻²⁷ = 1.67 × 10⁻²¹ kg = 1.67 × 10⁻²¹ kg (1.67 in units of 10⁻²¹ kg). (b) spacing = (1 ÷ 1.0 × 10⁶)^(1/3) = 0.010 m. In mm: 0.010 × 1000 = 10. (c) The atoms still move randomly and collide with any surface, transferring momentum. Mark scheme (5 marks). C1: m = n × m_atom. A1: mass. C1: cube root. A1: d = 10 mm. B1: molecular impacts.', 5),
('bf36a113-9ac2-5a43-921f-7dd9b1b9da3c', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 46, 46, 'Liquid water has density 1000 kg m⁻³. At 100 °C and atmospheric pressure the steam above it has density 0.60 kg m⁻³. The molar mass of water is 0.018 kg mol⁻¹. (a) Calculate the volume available to each molecule in the liquid. (b) Calculate the volume available to each molecule in the steam. (c) Hence calculate the ratio of the mean spacing of molecules in the steam to that in the liquid, and comment on what this means for the kinetic-theory assumptions. Give only the ratio from (c). Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '11.86', NULL, false, NULL, false, NULL, '(a) V₁ = 0.018 ÷ (1000 × 6.02 × 10²³) = 2.99 × 10⁻²⁹ m³. (b) V₂ = 0.018 ÷ (0.60 × 6.02 × 10²³) = 4.98 × 10⁻²⁶ m³. (c) Spacing scales as the cube root of the volume per molecule, so the ratio is (1000 ÷ 0.60)^(1/3) = 11.9. In the vapour the molecules are about twelve diameters apart, so their own volume and the forces between them are small, as the ideal-gas model assumes. Mark scheme (5 marks). C1: volume per molecule in liquid = M/(ρN_A). C1: volume per molecule in steam. M1: spacing ∝ (volume per molecule)^(1/3). B1: molecules far apart, so ideal-gas assumptions reasonable. A1: ratio = 11.9.', 5),
('a2094367-6cea-5071-b143-60390ecf6c19', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 47, 47, 'Air under room conditions contains about 2.5 × 10²⁵ molecules per cubic metre. (a) Calculate the number of molecules in 1.0 cm³ of air. (b) A machine could count 1.0 × 10⁹ molecules every second. Calculate how long it would take to count the molecules in 1.0 cm³, in years (1 year = 3.15 × 10⁷ s). (c) Comment on what this suggests about the size of molecules. Give only the answer to (b), in years.', NULL, 3, 'numeric'::answer_type, '793.7', 'years', false, NULL, false, NULL, '(a) 1.0 cm³ = 1.0 × 10⁻⁶ m³, so N = 2.5 × 10²⁵ × 1.0 × 10⁻⁶ = 2.5 × 10¹⁹. (b) t = 2.5 × 10¹⁹ ÷ 1.0 × 10⁹ = 2.5 × 10¹⁰ s. In years: 2.5 × 10¹⁰ ÷ 3.15 × 10⁷ = 794. (c) Even a tiny volume holds an enormous number of molecules, so each molecule must be extremely small. Mark scheme (5 marks). C1: 1.0 cm³ = 1.0 × 10⁻⁶ m³. C1: N = 2.5 × 10¹⁹. C1: t = N ÷ counting rate. B1: molecules are extremely small. A1: t = 794 years.', 5),
('2dfac9a5-6c51-562b-951c-3a0c48107165', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 48, 48, 'A party balloon loses helium through its rubber skin at a steady 2.0 × 10⁻⁴ mol per hour. (a) Calculate the number of helium atoms that escape each second. (b) Calculate the mass of helium lost in 24 hours, in mg (molar mass of helium 4.0 g mol⁻¹). (c) Suggest why helium escapes through the rubber faster than air does. Give only the answer to (a), in s⁻¹. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '3.344e16', 's⁻¹', false, NULL, false, NULL, '(a) Atoms per second = 2.0 × 10⁻⁴ × 6.02 × 10²³ ÷ 3600 = 3.34 × 10¹⁶ s⁻¹. (b) Mass lost = 2.0 × 10⁻⁴ × 24 × 4.0 = 0.0192 g, which is 19.2 mg. (c) Helium atoms are much smaller and lighter than nitrogen or oxygen molecules, so at the same temperature they move faster and slip between the rubber molecules more easily. Mark scheme (5 marks). C1: N = nN_A. C1: per hour → per second (÷ 3600). C1: mass = n × M over 24 h. B1: smaller, faster atoms. A1: rate = 3.34 × 10¹⁶ s⁻¹.', 5),
('86387d99-134b-5b63-b2eb-36f5b065ad5e', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 49, 49, 'A gas cylinder holds a mixture of 0.10 kg of helium (molar mass 0.0040 kg mol⁻¹) and 0.10 kg of argon (molar mass 0.040 kg mol⁻¹). (a) Calculate the amount of each gas in moles. (b) Calculate the total number of atoms in the cylinder. (c) Calculate the fraction of the atoms that are helium. (d) Explain why equal masses of the two gases contain such different numbers of atoms. Give only the answer to (c). Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '0.9091', NULL, false, NULL, false, NULL, '(a) n(He) = 0.10 ÷ 0.0040 = 25 mol. n(Ar) = 0.10 ÷ 0.040 = 2.5 mol. (b) N = 27.5 × 6.02 × 10²³ = 1.66 × 10²⁵. (c) Fraction = 25 ÷ 27.5 = 0.909. (d) An argon atom has about ten times the mass of a helium atom, so the same mass contains about one tenth as many atoms. Mark scheme (5 marks). C1: n = m/M for both gases. C1: total N = (25 + 2.5)N_A. M1: fraction = n(He)/total. B1: argon atom ten times as massive. A1: fraction = 0.909.', 5),
('e2a66595-660d-5793-9099-831db4db0a0d', '468b27d0-3cef-43ee-aeef-09b1a340050f', '975bd5dc-77a0-497e-8745-a6f0d01bd40a', 'a-level', '20.1', '9702 coursebook 20.1 · Particles of a gas', 50, 50, 'In a smoke cell, a smoke particle is a sphere of diameter 1.0 µm and density 1500 kg m⁻³. An air molecule has mass 4.8 × 10⁻²⁶ kg. (a) Calculate the mass of the smoke particle. (b) Calculate how many times more massive the smoke particle is than an air molecule. (c) Explain why the motion of the smoke particle can be seen but the air molecules cannot. (d) The smoke particle and the air molecules have the same mean kinetic energy. Calculate the ratio (r.m.s. speed of air molecules) ÷ (r.m.s. speed of smoke particles). Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '1.279e5', NULL, false, NULL, false, NULL, '(a) m = 1500 × π/6 × (1.0 × 10⁻⁶)³ = 7.85 × 10⁻¹⁶ kg. (b) Mass ratio = 7.854 × 10⁻¹⁶ ÷ 4.8 × 10⁻²⁶ = 1.64 × 10¹⁰. (c) The smoke particle is large enough to scatter light into the microscope; the molecules are far too small to see, and only their uneven impacts on the particle reveal them. (d) Equal ½m⟨c²⟩ means c_rms ∝ 1/√m, so the speed ratio = √(1.636 × 10¹⁰) = 1.28 × 10⁵. Mark scheme (6 marks). C1: m = ρ × (π/6)d³. C1: mass ratio. B1: particle visible, molecules too small. M1: equal mean KE so c_rms ∝ 1/√m. C1: square root of mass ratio. A1: ratio = 1.28 × 10⁵.', 6)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('fe88ffb3-1230-5c92-b475-5f1bb97efd09', 'faf61d35-93c5-564e-aba5-0fa4818aa3fe', 'The molecules attract each other strongly', 'A', false, 0),
('b26a5f33-7c50-5630-9b73-28526ecd16f0', 'faf61d35-93c5-564e-aba5-0fa4818aa3fe', 'The molecules are at rest', 'B', false, 1),
