('dd0794ea-2f1a-5a87-b2be-54598583505d', 'f740ee54-a8a2-5a6c-bc13-d6940ad66ff5', 'Evaporation', 'D', false, 3),
('6dd4ba56-b699-5532-a4e1-fe46036b570c', '3faf2fd2-0624-51da-bd49-a26e5d5b5f33', 'Convection currents in the air', 'A', false, 0),
('44301769-6c59-5786-91b1-8e4afc945c62', '3faf2fd2-0624-51da-bd49-a26e5d5b5f33', 'The smoke particle''s own vibration', 'B', false, 1),
('dfdec88b-25aa-54aa-a535-86f5b0035fcb', '3faf2fd2-0624-51da-bd49-a26e5d5b5f33', 'Electric charges on the smoke', 'C', false, 2),
('c2c6d276-51ee-56a0-87df-ad16ee6ccc77', '3faf2fd2-0624-51da-bd49-a26e5d5b5f33', 'Uneven bombardment by much smaller, fast-moving air molecules', 'D', true, 3),
('3a0e30d7-c431-5df9-a6b5-6415b91e3e2c', '480364fe-19ad-5068-bfb5-eb51af0b2ea4', 'Gas molecules have no mass', 'A', false, 0),
('ef66e47f-61ce-5e82-ab4f-0579a637ef41', '480364fe-19ad-5068-bfb5-eb51af0b2ea4', 'The molecules are far apart on average, so the forces are negligible except during collisions', 'B', true, 1),
('20eafb71-9b26-5c9b-82e0-4bc1c8980849', '480364fe-19ad-5068-bfb5-eb51af0b2ea4', 'Gas molecules are charged', 'C', false, 2),
('b0d38c0c-8a75-50ca-b301-d8c6dee6f167', '480364fe-19ad-5068-bfb5-eb51af0b2ea4', 'The molecules are at rest', 'D', false, 3),
('91cad96a-1592-52e1-933e-2d5a39dbaa7f', 'da80ccf9-033b-5a8b-8263-ef071ec64e16', 'In circles', 'A', false, 0),
('cb472de2-b412-5898-8033-049d2cd91626', 'da80ccf9-033b-5a8b-8263-ef071ec64e16', 'With constant acceleration downwards', 'B', false, 1),
('421ba7fa-bb28-5d98-b723-3ef61bf9c5a0', 'da80ccf9-033b-5a8b-8263-ef071ec64e16', 'In straight lines at constant speed', 'C', true, 2),
('14919d49-ff08-540b-97d2-fb201b528987', 'da80ccf9-033b-5a8b-8263-ef071ec64e16', 'They do not move between collisions', 'D', false, 3),
('041bf460-4c75-5f74-8e05-3a8c3f370168', '3272c4a0-c642-59d3-90b0-f256622c2030', 'Its molecules move randomly in all directions with little attraction between them', 'A', true, 0),
('8f8272f3-d47a-593d-9a1c-c02052666d09', '3272c4a0-c642-59d3-90b0-f256622c2030', 'Its molecules repel each other strongly', 'B', false, 1),
('367fdafb-6e40-5fab-9fe0-4235dad8dbee', '3272c4a0-c642-59d3-90b0-f256622c2030', 'Gravity pulls the molecules outwards', 'C', false, 2),
('fe5415e7-e00f-54d8-888f-2144137e3bfb', '3272c4a0-c642-59d3-90b0-f256622c2030', 'The container attracts the molecules', 'D', false, 3),
('70f371ae-a6a5-5b8f-912d-a25089d1ac51', '03fb52d2-9c75-5483-be80-2dc54c38b322', 'A gas has a fixed volume', 'A', false, 0),
('bceb5d44-bd3c-5cd1-8e08-2e4b345f904b', '03fb52d2-9c75-5483-be80-2dc54c38b322', 'Gases are heavier than liquids', 'B', false, 1),
('36d71c27-17f0-5cb6-8692-44fabee27b29', '03fb52d2-9c75-5483-be80-2dc54c38b322', 'Gases cannot be compressed', 'C', false, 2),
('f7b7ba5e-0376-5028-a5bd-1bbfe3a9bb9e', '03fb52d2-9c75-5483-be80-2dc54c38b322', 'A smell spreading across a room even with no draughts', 'D', true, 3),
('6c57b379-0497-5956-ab90-e2caf6b1551f', '46f74498-057d-5566-88f0-9f913c1fa576', 'The molecules stick together', 'A', false, 0),
('27eb2589-86ba-56d2-95ee-6de3b1aeb836', '46f74498-057d-5566-88f0-9f913c1fa576', 'Total kinetic energy is conserved in each collision', 'B', true, 1),
('d6a1dbe1-38b1-5c38-9c80-546441f10b4a', '46f74498-057d-5566-88f0-9f913c1fa576', 'Momentum is lost', 'C', false, 2),
('995cd52c-d620-59bd-940e-09d3a6894712', '46f74498-057d-5566-88f0-9f913c1fa576', 'The molecules change shape', 'D', false, 3),
('af2748ec-ee55-5265-b62a-330c0df3542c', '0eca563a-266f-59a0-bf16-4cb2846591e0', 'The smoke particles become lighter', 'A', false, 0),
('f8cac88e-2f26-5d80-a99a-4ef6fbefcc9a', '0eca563a-266f-59a0-bf16-4cb2846591e0', 'There are fewer air molecules', 'B', false, 1),
('b5d7e5d7-9cfc-58a7-9486-6bec0995b33d', '0eca563a-266f-59a0-bf16-4cb2846591e0', 'The air molecules move faster, so their impacts are harder and more frequent', 'C', true, 2),
('3d12e184-9f85-5ffa-bc02-5eade2c3f393', '0eca563a-266f-59a0-bf16-4cb2846591e0', 'Convection currents are stronger', 'D', false, 3),
('0b1843e0-23cc-5555-88c2-71061bfd3f88', '69781439-6cec-59bc-a64d-6727a51450b0', 'All the molecules move at the same speed', 'A', true, 0),
('628fb9fd-54b4-59f5-a2cf-b9a7a1cc237b', '69781439-6cec-59bc-a64d-6727a51450b0', 'The molecules move randomly', 'B', false, 1),
('dea9a0e6-7717-53f7-a8b2-7ba2f51d70c1', '69781439-6cec-59bc-a64d-6727a51450b0', 'There are a very large number of molecules', 'C', false, 2),
('0ac5f5fc-1250-5e9d-a98d-91ded1145aa5', '69781439-6cec-59bc-a64d-6727a51450b0', 'The duration of a collision is very short compared with the time between collisions', 'D', false, 3),
('aab6eddd-fec5-51b2-be69-ee75822ba998', 'f17ade8e-d626-5393-b799-2ba7af8696db', 'Collisions are elastic', 'A', false, 0),
('788f2dfe-e3ef-5002-9dbe-e77bf0126a61', 'f17ade8e-d626-5393-b799-2ba7af8696db', 'The molecules move randomly', 'B', false, 1),
('dbfd70e6-1f73-51aa-aac2-1d8d7fa1c72f', 'f17ade8e-d626-5393-b799-2ba7af8696db', 'The molecules have a range of speeds', 'C', false, 2),
('087c602f-e4bf-580d-9944-bf6632039a03', 'f17ade8e-d626-5393-b799-2ba7af8696db', 'The volume of the molecules is negligible compared with the volume of the gas', 'D', true, 3),
('ed5a47ff-c635-59c1-97fb-da3be47ce97a', '5ac5bcba-6e88-5abb-85cf-033bf9a50b6b', 'Larger particles are hit less often', 'A', false, 0),
('0d833810-dd00-5298-9e99-9ffa0b056a9a', '5ac5bcba-6e88-5abb-85cf-033bf9a50b6b', 'The random imbalance of impacts is smaller relative to their larger mass and size', 'B', true, 1),
('c6f342fe-9420-56b6-a8d1-f620ee9d1a79', '5ac5bcba-6e88-5abb-85cf-033bf9a50b6b', 'Larger particles are colder', 'C', false, 2),
('9ada7882-f45e-5ed3-9797-8b7977843788', '5ac5bcba-6e88-5abb-85cf-033bf9a50b6b', 'Larger particles are attracted to the walls', 'D', false, 3),
('66c7b7da-cf61-54e6-a6f8-22165b2abda5', '15e4252f-7f67-5c37-9023-efd8014f4678', 'So that collisions are inelastic', 'A', false, 0),
('6060e2f2-c9d6-5064-b676-080e8273ebe4', '15e4252f-7f67-5c37-9023-efd8014f4678', 'So that the molecules have no speed', 'B', false, 1),
('d82a12fd-1735-59a3-bbe6-afccf2fa6385', '15e4252f-7f67-5c37-9023-efd8014f4678', 'So that at any instant almost all molecules are moving freely, and forces act only during brief impacts', 'C', true, 2),
('44fb4bb9-a209-5e30-acf4-acec8626e22e', '15e4252f-7f67-5c37-9023-efd8014f4678', 'So that gravity can be ignored', 'D', false, 3),
('b7b5a7ad-9d37-58a8-b497-de677f2f1cab', 'a02679b3-df2c-5de4-8f3c-84874353fa25', 'That the molecules'' own volume and the forces between them are negligible', 'A', true, 0),
('a4b535f8-d486-5923-ab2c-e7d8f21657ee', 'a02679b3-df2c-5de4-8f3c-84874353fa25', 'That the molecules move randomly', 'B', false, 1),
('f8b35666-8a05-5e5e-ad1a-7e3c39a86c1f', 'a02679b3-df2c-5de4-8f3c-84874353fa25', 'That there are many molecules', 'C', false, 2),
('2723f69c-c781-52cf-994f-b9568742c3fd', 'a02679b3-df2c-5de4-8f3c-84874353fa25', 'That the collisions are short', 'D', false, 3),
('8befc55a-40b5-5d96-b319-a06d8b8f0b69', '9e99e8ed-0adc-56a0-8893-914c91621f4f', 'All molecules have the same speed', 'A', false, 0),
('65022c2a-1c08-558c-a931-ae572323292d', '9e99e8ed-0adc-56a0-8893-914c91621f4f', 'The speeds gradually fall to zero', 'B', false, 1),
('94ff93dd-5e93-504e-a0d7-2d629bcb58f5', '9e99e8ed-0adc-56a0-8893-914c91621f4f', 'Faster molecules gradually escape until all have the same speed', 'C', false, 2),
('9c1c8e44-12e8-5ca9-8daa-ffc0615d4529', '9e99e8ed-0adc-56a0-8893-914c91621f4f', 'The molecules have a wide range of speeds, but the distribution stays the same over time', 'D', true, 3),
('8d207ce1-ea4d-5f69-b17c-caa0c540cd1b', 'd0e42edb-8e88-55ec-a583-c309b2031044', 'The student is right', 'A', false, 0),
('2f4987c1-18b6-5f78-a1ca-bd1ce2346c85', 'd0e42edb-8e88-55ec-a583-c309b2031044', 'For an ideal gas the collisions are elastic: the molecules rebound with the same speed, so no kinetic energy is lost', 'B', true, 1),
('af90347f-3fce-5e00-ac5c-6587a305ee9f', 'd0e42edb-8e88-55ec-a583-c309b2031044', 'The molecules speed up at the walls', 'C', false, 2),
('70bf6720-3e52-5e40-911e-6fc4f533be3d', 'd0e42edb-8e88-55ec-a583-c309b2031044', 'The walls absorb the molecules', 'D', false, 3),
('a53138e3-7ded-551a-aa46-2ff9e5bcae3b', 'c74977bf-6ab5-5770-bd52-bcc23257b91a', 'They have no mass', 'A', false, 0),
('ec8b6aeb-9779-5bea-880c-69c0bac86122', 'c74977bf-6ab5-5770-bd52-bcc23257b91a', 'They are all identical', 'B', false, 1),
('3acba16c-6f28-53f7-ad29-b2f6acdce1d9', 'c74977bf-6ab5-5770-bd52-bcc23257b91a', 'Their size is tiny compared with the distances they travel between collisions', 'C', true, 2),
('7f4c618c-eb49-5881-9759-cda7f8f7baaa', 'c74977bf-6ab5-5770-bd52-bcc23257b91a', 'They never collide with each other', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('3f2f6087-0561-53c8-a8f0-f0838d01b2a0', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 7, 7, 'How does the kinetic model explain the pressure of a gas on its container?', NULL, 1, 'multiple_choice'::answer_type, 'Molecules collide with the walls and change momentum; the walls exert forces on them and they exert equal forces on the walls', NULL, false, NULL, false, NULL, 'Each collision gives a change of momentum; the rate of change of momentum per unit area is the pressure. Mark scheme (1 mark). B1: C (Molecules collide with the walls and change momentum; the walls exert forces on them and they exert equal forces on the walls).', 1),
('0d7046a8-d116-5d4f-b771-bb7efbe2e12c', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 8, 8, 'A gas exerts a pressure of 1.2 × 10⁵ Pa on a piston of area 0.015 m². Calculate the force on the piston.', NULL, 1, 'numeric'::answer_type, '1800', 'N', false, NULL, false, NULL, 'F = pA = 1.2 × 10⁵ × 0.015 = 1800 N. Mark scheme (2 marks). C1: F = pA. A1: F = 1800 N.', 2),
('46e3534b-11b5-5cf0-bfe1-e19340764ccf', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 9, 9, 'A force of 650 N acts uniformly on a valve of area 4.0 × 10⁻³ m². Calculate the pressure.', NULL, 1, 'numeric'::answer_type, '1.625e5', 'Pa', false, NULL, false, NULL, 'p = F/A = 650 ÷ 4.0 × 10⁻³ = 1.6 × 10⁵ Pa. Mark scheme (2 marks). C1: p = F/A. A1: p = 1.6 × 10⁵ Pa.', 2),
('a0cb516a-2a6d-5cfd-943a-63673fb630b5', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 10, 10, 'A molecule of mass m moving at speed u hits a wall at right angles and rebounds elastically. What is the magnitude of its change of momentum?', NULL, 1, 'multiple_choice'::answer_type, '2mu', NULL, false, NULL, false, NULL, 'Momentum changes from +mu to −mu: a change of 2mu. Mark scheme (1 mark). B1: A (2mu).', 1),
('55483973-e15b-589c-b4d0-25347b62ea67', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 11, 11, 'A nitrogen molecule (mass 4.65 × 10⁻²⁶ kg) moving at 500 m s⁻¹ rebounds elastically at right angles from a wall. Calculate its change in momentum, in units of 10⁻²³ kg m s⁻¹.', NULL, 1, 'numeric'::answer_type, '4.65', '10⁻²³ kg m s⁻¹', false, NULL, false, NULL, 'Δp = 2mu = 2 × 4.65 × 10⁻²⁶ × 500 = 4.65 × 10⁻²³ kg m s⁻¹. Mark scheme (2 marks). C1: Δp = 2mu. A1: Δp = 4.65 × 10⁻²³ kg m s⁻¹.', 2),
('527e4020-46a9-5d90-a379-5a2ccd76da7b', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 12, 12, 'A gas in a sealed rigid container is heated. Why does its pressure rise?', NULL, 1, 'multiple_choice'::answer_type, 'The molecules move faster, so they hit the walls harder and more often', NULL, false, NULL, false, NULL, 'Higher temperature means higher molecular speeds: more momentum change per collision and more collisions per second. Mark scheme (1 mark). B1: D (The molecules move faster, so they hit the walls harder and more often).', 1),
('783219b0-5a01-568f-9826-b401428cbdda', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 13, 13, 'The number of molecules in a container is doubled at constant temperature and volume. What happens to the pressure?', NULL, 1, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'Twice as many molecules hit the walls per second with the same speeds, so the pressure doubles. Mark scheme (1 mark). B1: B (It doubles).', 1),
('35ae7445-0d84-5505-85e3-92e6abb1ef39', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 14, 14, 'Which equation relates the pressure of an ideal gas to the mean square speed of its molecules?', NULL, 1, 'multiple_choice'::answer_type, 'pV = ⅓Nm⟨c²⟩', NULL, false, NULL, false, NULL, 'Derived from Newton''s laws applied to molecular collisions: pV = ⅓Nm⟨c²⟩. Mark scheme (1 mark). B1: C (pV = ⅓Nm⟨c²⟩).', 1),
('0a9f355b-9918-58db-a0b2-b6aa07000603', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 15, 15, 'A gas has density 1.8 kg m⁻³ and mean square speed 2.5 × 10⁵ m² s⁻². Calculate its pressure using p = ⅓ρ⟨c²⟩.', NULL, 1, 'numeric'::answer_type, '1.5e5', 'Pa', false, NULL, false, NULL, 'p = ⅓ρ⟨c²⟩ = 1.8 × 2.5 × 10⁵ ÷ 3 = 1.5 × 10⁵ Pa. Mark scheme (2 marks). C1: p = ⅓ρ⟨c²⟩. A1: p = 1.5 × 10⁵ Pa.', 2),
('829b08cf-ed34-529c-ba6b-8002e4aecb2b', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 16, 16, 'Why does the factor ⅓ appear in pV = ⅓Nm⟨c²⟩?', NULL, 1, 'multiple_choice'::answer_type, 'Molecules move in three dimensions; on average one third of ⟨c²⟩ is in the direction perpendicular to a given wall', NULL, false, NULL, false, NULL, '⟨c²⟩ = ⟨cₓ²⟩ + ⟨c_y²⟩ + ⟨c_z²⟩ and, by symmetry, each is ⅓⟨c²⟩. Mark scheme (1 mark). B1: A (Molecules move in three dimensions; on average one third of ⟨c²⟩ is in the direction perpendicular to a given wall).', 1),
('e8a2e472-fc67-5895-a464-b7ac9a7a5b8a', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 17, 17, 'Calculate the force exerted by atmospheric pressure (1.0 × 10⁵ Pa) on a window of area 1.2 m².', NULL, 1, 'numeric'::answer_type, '1.2e5', 'N', false, NULL, false, NULL, 'F = pA = 1.0 × 10⁵ × 1.2 = 1.2 × 10⁵ N. Mark scheme (2 marks). C1: F = pA. A1: F = 1.2 × 10⁵ N.', 2),
('b285040b-cd08-56d6-aa13-215ff2882a40', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 18, 18, 'Why doesn''t the large force of the atmosphere on a window break it?', NULL, 1, 'multiple_choice'::answer_type, 'Air pushes with an almost equal force on the other side', NULL, false, NULL, false, NULL, 'The pressures on both sides are about equal, so the resultant force is nearly zero. Mark scheme (1 mark). B1: D (Air pushes with an almost equal force on the other side).', 1),
('17e12686-129c-5cba-9f6d-c6d3c6fd905a', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 19, 19, 'A gas has pressure 2.0 × 10⁵ Pa and density 2.4 kg m⁻³. Calculate the mean square speed of its molecules.', NULL, 1, 'numeric'::answer_type, '2.5e5', 'm² s⁻²', false, NULL, false, NULL, '⟨c²⟩ = 3p/ρ = 3 × 2.0 × 10⁵ ÷ 2.4 = 2.5 × 10⁵ m² s⁻². Mark scheme (2 marks). C1: rearranged p = ⅓ρ⟨c²⟩. A1: ⟨c²⟩ = 2.5 × 10⁵ m² s⁻².', 2),
('2d2ce6a5-adcb-5c0e-b644-1a404087e5b1', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 20, 20, 'A balloon is squeezed to half its volume at constant temperature. Why does the pressure double?', NULL, 1, 'multiple_choice'::answer_type, 'The same molecules hit the smaller wall area twice as often', NULL, false, NULL, false, NULL, 'At constant T the speeds are unchanged; halving V doubles the number density and so the collision rate per unit area. Mark scheme (1 mark). B1: B (The same molecules hit the smaller wall area twice as often).', 1),
('322d8806-d7fa-5c67-9b79-317c1b92a41b', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 21, 21, 'Calculate the root-mean-square speed of molecules whose mean square speed is 1.6 × 10⁵ m² s⁻².', NULL, 1, 'numeric'::answer_type, '400', 'm s⁻¹', false, NULL, false, NULL, 'c_rms = √⟨c²⟩ = √(1.6 × 10⁵) = 400 m s⁻¹. Mark scheme (2 marks). C1: square root. A1: c_rms = 400 m s⁻¹.', 2),
('25219a61-8bc2-59f1-9a11-7631d1f81b43', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 22, 22, 'Which quantity is the root-mean-square speed of gas molecules?', NULL, 1, 'multiple_choice'::answer_type, 'The square root of the average of the squares of the speeds', NULL, false, NULL, false, NULL, 'c_rms = √⟨c²⟩: square each speed, average, then take the square root. Mark scheme (1 mark). B1: C (The square root of the average of the squares of the speeds).', 1),
('e438459e-70f7-5d47-8ced-49a61facab8a', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 23, 23, 'Three molecules have speeds 200, 400 and 600 m s⁻¹. Calculate their mean square speed and their root-mean-square speed. Give the r.m.s. speed.', NULL, 2, 'numeric'::answer_type, '432', 'm s⁻¹', false, NULL, false, NULL, '⟨c²⟩ = (200² + 400² + 600²) ÷ 3 = 1.87 × 10⁵ m² s⁻². c_rms = √1.867 × 10⁵ = 432 m s⁻¹ (the mean speed is 400 m s⁻¹). Mark scheme (3 marks). C1: squares averaged. C1: square root. B1: differs from mean speed.', 3),
('6717ec14-9ffd-5a9d-8433-ea49feb021d6', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 24, 24, 'A container of volume 0.040 m³ holds 1.5 × 10²⁴ molecules, each of mass 5.3 × 10⁻²⁶ kg, with r.m.s. speed 480 m s⁻¹. Calculate the pressure.', NULL, 2, 'numeric'::answer_type, '1.526e5', 'Pa', false, NULL, false, NULL, 'p = Nm⟨c²⟩/(3V) = 1.5 × 10²⁴ × 5.3 × 10⁻²⁶ × 480² ÷ (3 × 0.040) = 1.53 × 10⁵ Pa. Mark scheme (4 marks). C1: pV = ⅓Nm⟨c²⟩. C1: ⟨c²⟩ = c_rms². C1: substitution. A1: p = 1.53 × 10⁵ Pa.', 4),
('16aedbce-9f6c-5ab1-8ec4-854406f649c5', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 25, 25, 'In deriving pV = ⅓Nm⟨c²⟩, a molecule moving at speed u between two walls a distance L apart hits one wall how often?', NULL, 2, 'multiple_choice'::answer_type, 'Once every 2L/u seconds', NULL, false, NULL, false, NULL, 'It travels to the far wall and back (2L) between successive hits on the same wall. Mark scheme (3 marks). C1: round trip 2L. C1: time = 2L/u. A1: A (Once every 2L/u seconds).', 3),
('50bc2f5a-78c6-5ddc-bc2b-ddb4ffca5926', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 26, 26, 'A molecule of mass 4.8 × 10⁻²⁶ kg bounces back and forth between two walls 0.20 m apart at 450 m s⁻¹. Calculate the average force it exerts on one wall, in units of 10⁻²³ N.', NULL, 2, 'numeric'::answer_type, '4860', '10⁻²³ N', false, NULL, false, NULL, 'Δp per hit = 2mu, hits per second = u/2L, so F = mu²/L = 4.8 × 10⁻²⁶ × 450² ÷ 0.20 = 4.86 × 10⁻²⁰ N. Mark scheme (3 marks). C1: Δp = 2mu. C1: rate u/2L. C1: F = mu²/L.', 3),
('d092af62-3c9d-52b4-b4e2-990106b5265b', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 27, 27, 'Gas A has molecules of mass m and gas B has molecules of mass 4m. They have the same pressure, volume and number of molecules. Which is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The r.m.s. speed in A is twice that in B', NULL, false, NULL, false, NULL, 'pV = ⅓Nm⟨c²⟩: with pV and N equal, m⟨c²⟩ is equal, so ⟨c²⟩ ∝ 1/m and c_rms ∝ 1/√m. Mark scheme (4 marks). C1: m⟨c²⟩ constant. C1: c_rms ∝ 1/√m. C1: factor 2. A1: D (The r.m.s. speed in A is twice that in B).', 4),
('ec9c5b38-1f65-5b15-98ac-dd1286439661', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 28, 28, 'At sea level air has pressure 1.01 × 10⁵ Pa and density 1.29 kg m⁻³. Calculate the r.m.s. speed of the air molecules.', NULL, 2, 'numeric'::answer_type, '484.6', 'm s⁻¹', false, NULL, false, NULL, 'c_rms = √(3p/ρ) = √(3 × 1.01 × 10⁵ ÷ 1.29) = 485 m s⁻¹. Mark scheme (3 marks). C1: p = ⅓ρ⟨c²⟩. C1: rearranged. C1: square root.', 3),
('20d0c01a-8f0b-545a-bf85-eb312655c8b2', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 29, 29, 'A gas is heated at constant volume until the r.m.s. speed of its molecules doubles. What happens to its pressure?', NULL, 2, 'multiple_choice'::answer_type, 'It increases by a factor of 4', NULL, false, NULL, false, NULL, 'p ∝ ⟨c²⟩ at constant V and N: doubling c_rms quadruples ⟨c²⟩. Mark scheme (3 marks). C1: p ∝ ⟨c²⟩. C1: factor 4. A1: B (It increases by a factor of 4).', 3),
('6326ab9f-24d7-566d-a10a-62b131c186f9', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 30, 30, 'Five molecules have speeds 300, 350, 400, 450, 500 m s⁻¹. Calculate (a) the mean speed and (b) the r.m.s. speed. Give only the answer to (b).', NULL, 2, 'numeric'::answer_type, '406.2', 'm s⁻¹', false, NULL, false, NULL, '(a) mean = 2000 ÷ 5 = 400 m s⁻¹. (b) ⟨c²⟩ = (300² + 350² + 400² + 450² + 500²) ÷ 5 = 1.65 × 10⁵ m² s⁻². c_rms = √1.650 × 10⁵ = 406 m s⁻¹. Mark scheme (4 marks). B1: mean speed. C1: mean square. C1: square root. A1: c_rms = 406 m s⁻¹.', 4),
('cb6bf1ce-3dc5-5496-a481-80388e50ae77', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 31, 31, 'Why does a gas exert the same pressure in all directions?', NULL, 2, 'multiple_choice'::answer_type, 'The molecules move randomly, so on average equal numbers move in every direction', NULL, false, NULL, false, NULL, 'Random motion means no preferred direction, so the momentum transfer per unit area is the same on every wall. Mark scheme (3 marks). C1: random motion. C1: no preferred direction. A1: C (The molecules move randomly, so on average equal numbers move in every direction).', 3),
('795dc2db-cb3c-59ef-9e41-bf368a061996', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 32, 32, 'A gas at 1.5 × 10⁵ Pa has molecules with r.m.s. speed 520 m s⁻¹. Calculate its density.', NULL, 2, 'numeric'::answer_type, '1.664', 'kg m⁻³', false, NULL, false, NULL, 'ρ = 3p/⟨c²⟩ = 3 × 1.5 × 10⁵ ÷ 520² = 1.66 kg m⁻³. Mark scheme (3 marks). C1: p = ⅓ρ⟨c²⟩. C1: rearranged. A1: ρ = 1.66 kg m⁻³.', 3),
('0fa12f46-d0e1-557d-86e0-0e6b1219ab17', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 33, 33, 'A tyre pump compresses air to half its volume quickly, and the temperature rises. Which statement explains why the pressure more than doubles?', NULL, 2, 'multiple_choice'::answer_type, 'The number density doubles AND the molecules move faster', NULL, false, NULL, false, NULL, 'Both factors in p = ⅓(N/V)m⟨c²⟩ increase. Mark scheme (3 marks). C1: N/V doubles. C1: ⟨c²⟩ increases. A1: A (The number density doubles AND the molecules move faster).', 3),
('bba8babb-884d-51b7-826b-a9ff42d17f39', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 34, 34, 'A cubic box of side 0.10 m contains 3.0 × 10²² helium atoms (mass 6.6 × 10⁻²⁷ kg) with r.m.s. speed 1.3 × 10³ m s⁻¹. Calculate the force on one face of the box.', NULL, 2, 'numeric'::answer_type, '1115', 'N', false, NULL, false, NULL, 'p = Nm⟨c²⟩/3V = 3.0 × 10²² × 6.6 × 10⁻²⁷ × (1.3 × 10³)² ÷ (3 × 1.0 × 10⁻³) = 1.12 × 10⁵ Pa. F = pA = 1.115 × 10⁵ × 0.010 = 1120 N. Mark scheme (4 marks). C1: V = L³. C1: p from kinetic formula. C1: F = pA. A1: F = 1120 N.', 4),
('26b67686-2835-51a1-a114-42bc303dad80', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 35, 35, 'In the derivation of pV = ⅓Nm⟨c²⟩, collisions between molecules are ignored. Why does this not affect the result?', NULL, 2, 'multiple_choice'::answer_type, 'Elastic collisions between molecules just exchange momentum; the average momentum carried to the walls is unchanged', NULL, false, NULL, false, NULL, 'Momentum and kinetic energy are conserved in molecular collisions, so the total rate of momentum transfer to the walls is unchanged. Mark scheme (3 marks). C1: elastic collisions. C1: momentum conserved overall. A1: D (Elastic collisions between molecules just exchange momentum; the average momentum carried to the walls is unchanged).', 3),
('78ac6ec5-48e8-51e6-937a-82081ae44451', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 36, 36, 'Calculate the total kinetic energy of the molecules in 0.020 m³ of a gas at 1.0 × 10⁵ Pa, using pV = ⅓Nm⟨c²⟩ and Ek = ½Nm⟨c²⟩.', NULL, 2, 'numeric'::answer_type, '3000', 'J', false, NULL, false, NULL, 'Nm⟨c²⟩ = 3pV, so total Ek = ½ × 3pV = 1.5 × 1.0 × 10⁵ × 0.020 = 3000 J. Mark scheme (3 marks). C1: Nm⟨c²⟩ = 3pV. C1: Ek = (3/2)pV. A1: Ek = 3000 J.', 3),
('73944793-e7ba-5045-9747-308970bdbfe3', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 37, 37, 'A gas is compressed isothermally to one third of its volume. Which row is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Pressure ×3; r.m.s. speed unchanged; collision rate per unit area ×3', NULL, false, NULL, false, NULL, 'Isothermal: speeds unchanged. Number density ×3 so collisions per unit area ×3, and p ×3. Mark scheme (4 marks). C1: same T, same speeds. C1: density ×3. C1: p ×3. A1: B (Pressure ×3; r.m.s. speed unchanged; collision rate per unit area ×3).', 4),
('e603f987-e7f4-561c-8b28-99dc282c1cb1', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 38, 38, 'The r.m.s. speed of hydrogen molecules in a sample is 1900 m s⁻¹ at a pressure of 1.0 × 10⁵ Pa. Calculate the density of the gas.', NULL, 2, 'numeric'::answer_type, '0.0831', 'kg m⁻³', false, NULL, false, NULL, 'ρ = 3p/c_rms² = 3 × 1.0 × 10⁵ ÷ 1900² = 0.0831 kg m⁻³. Mark scheme (3 marks). C1: p = ⅓ρ⟨c²⟩. C1: substitution. A1: ρ = 0.0831 kg m⁻³.', 3),
('e9d65820-7301-540f-a09d-684ca469a8ec', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 39, 39, 'A sample of methane contains 3.0 × 10²⁵ molecules in every cubic metre. Each molecule has mass 2.66 × 10⁻²⁶ kg and the r.m.s. speed of the molecules is 640 m s⁻¹. Calculate the pressure exerted by the methane.', NULL, 2, 'numeric'::answer_type, '1.09e5', 'Pa', false, NULL, false, NULL, 'Density ρ = 3.0 × 10²⁵ × 2.66 × 10⁻²⁶ = 0.798 kg m⁻³. p = ⅓ρ⟨c²⟩ = 0.798 × 640² ÷ 3 = 1.09 × 10⁵ Pa. Mark scheme (3 marks). C1: ρ = nm (number per m³ × molecular mass). C1: p = ⅓ρ⟨c²⟩ with ⟨c²⟩ = 640². A1: p = 1.09 × 10⁵ Pa.', 3),
('2372e77d-4292-5012-b426-6f1d38ebb3af', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 40, 40, 'A gas molecule of mass m travelling at speed u strikes a flat wall at 60° to the normal and rebounds elastically at 60° on the other side of the normal. What is the magnitude of its change of momentum?', NULL, 2, 'multiple_choice'::answer_type, 'mu', NULL, false, NULL, false, NULL, 'Only the component of velocity perpendicular to the wall, u cos 60° = u/2, reverses. Δp = 2m × u cos 60° = mu. The parallel component u sin 60° is unchanged, so "zero" and "√3 mu" are wrong, and "2mu" applies only to a head-on collision. Mark scheme (3 marks). C1: only the normal component reverses. C1: Δp = 2mu cos 60°. A1: C (mu).', 3),
('3fa46518-08fa-5a3b-9daf-854d92ebfe45', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 41, 41, 'A molecule of mass m moves in a cubical box of side L with velocity components (u, v, w). (a) Show that the force it exerts on the wall perpendicular to the x-direction is mu²/L. (b) Hence show that the pressure due to N molecules is p = Nm⟨u²⟩/L³. (c) Explain how this leads to pV = ⅓Nm⟨c²⟩. A box of side 0.30 m contains 6.0 × 10²³ molecules of mass 4.8 × 10⁻²⁶ kg with ⟨c²⟩ = 2.4 × 10⁵ m² s⁻². Give only the pressure.', NULL, 3, 'numeric'::answer_type, '85333', 'Pa', false, NULL, false, NULL, '(a) Δp = 2mu per hit; time between hits = 2L/u; F = 2mu ÷ (2L/u) = mu²/L. (b) Sum over N molecules: F = Nm⟨u²⟩/L, p = F/L² = Nm⟨u²⟩/L³. (c) Random motion: ⟨u²⟩ = ⅓⟨c²⟩ and L³ = V, so pV = ⅓Nm⟨c²⟩. p = 6.0 × 10²³ × 4.8 × 10⁻²⁶ × 2.4 × 10⁵ ÷ (3 × 0.30³) = 8.53 × 10⁴ Pa. Mark scheme (6 marks). M1: Δp = 2mu. M1: time between hits 2L/u. A1: F = mu²/L. M1: ⟨u²⟩ = ⅓⟨c²⟩. C1: substitution. A1: p = 8.53 × 10⁴ Pa.', 6),
('06739d14-8fd7-53b5-b539-66a1f8034a13', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 42, 42, 'A gas cylinder of volume 0.050 m³ contains oxygen at 2.0 × 10⁶ Pa. The molecules have r.m.s. speed 480 m s⁻¹. (a) Calculate the density of the oxygen. (b) Calculate the mass of oxygen. (c) Some gas is released at constant temperature until the pressure is 1.0 × 10⁶ Pa. Explain the effect on the r.m.s. speed and the density. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '1.302', 'kg', false, NULL, false, NULL, '(a) ρ = 3p/⟨c²⟩ = 3 × 2.0 × 10⁶ ÷ 480² = 26.0 kg m⁻³. (b) m = ρV = 26.04 × 0.050 = 1.30 kg. (c) Same temperature, so the r.m.s. speed is unchanged; the density halves. Mark scheme (5 marks). C1: ρ = 3p/⟨c²⟩. A1: ρ. C1: m = ρV. A1: m = 1.30 kg. B1: speed unchanged, density halves.', 5),
('6eeb8c93-faf4-5452-8a27-60e73921ac92', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 43, 43, 'In a beam experiment, 2.0 × 10²² nitrogen molecules per second (mass 4.65 × 10⁻²⁶ kg each), all moving at 500 m s⁻¹, strike a plate at right angles and rebound elastically. (a) Calculate the momentum change of one molecule. (b) Calculate the force on the plate. (c) The plate has area 4.0 cm². Calculate the pressure, and explain why a real gas pressure is a third of what this simple beam picture suggests. Give only the force in (b).', NULL, 3, 'numeric'::answer_type, '0.93', 'N', false, NULL, false, NULL, '(a) Δp = 2mu = 2 × 4.65 × 10⁻²⁶ × 500 = 4.65 × 10⁻²³ kg m s⁻¹. (b) F = rate × Δp = 2.0 × 10²² × 4.650 × 10⁻²³ = 0.930 N. (c) p = F/A = 0.9300 ÷ 4.0 × 10⁻⁴ = 2320 Pa. In a gas only the x-component of random velocities hits a wall: ⟨u²⟩ = ⅓⟨c²⟩. Mark scheme (6 marks). C1: Δp = 2mu. A1: Δp. C1: F = (N/t)Δp. A1: F = 0.930 N. C1: p = F/A. B1: random directions.', 6),
('847dd525-2db5-518f-af6f-ee9d43770123', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 44, 44, 'Air in a sealed container is at 1.0 × 10⁵ Pa with r.m.s. speed 500 m s⁻¹. (a) Calculate the density. (b) The container is heated until the r.m.s. speed is 600 m s⁻¹. Calculate the new pressure. (c) Calculate the ratio of new to old absolute temperatures. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '1.44e5', 'Pa', false, NULL, false, NULL, '(a) ρ = 3p/⟨c²⟩ = 3 × 1.0 × 10⁵ ÷ 500² = 1.2 kg m⁻³. (b) p ∝ ⟨c²⟩ at constant density: p = 1.0 × 10⁵ × (600 ÷ 500)² = 1.44 × 10⁵ Pa. (c) T ∝ ⟨c²⟩: ratio = 1.44. Mark scheme (5 marks). C1: ρ = 3p/⟨c²⟩. A1: ρ. C1: p ∝ ⟨c²⟩. A1: p = 1.44 × 10⁵ Pa. B1: T ratio 1.44.', 5),
('8019b4fc-7f75-5b82-81ea-1699abe72f82', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 45, 45, 'A spacecraft cabin of volume 25 m³ is filled with air (density 1.2 kg m⁻³, r.m.s. speed 500 m s⁻¹). (a) Calculate the pressure in the cabin. (b) A 1.0 cm² hole opens. Estimate the force pushing air out through it. (c) Using the kinetic model, explain why the cabin pressure falls only gradually. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '1e5', 'Pa', false, NULL, false, NULL, '(a) p = ⅓ρ⟨c²⟩ = 1.2 × 500² ÷ 3 = 1.00 × 10⁵ Pa. (b) F = pA = 1.00 × 10⁵ × 1.0 × 10⁻⁴ = 10 N. (c) Only molecules that happen to reach the hole escape; the number escaping per second is a small fraction of the huge number in the cabin. Mark scheme (6 marks). C1: p = ⅓ρ⟨c²⟩. C1: substitution. A1: p. C1: F = pA. B1: escape rate small. A1: p = 1.00 × 10⁵ Pa.', 6),
('e55d4743-4552-59cc-b091-6d951ab80c4b', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 46, 46, 'Gas pressure can be modelled with hailstones hitting a roof. During a storm 4.0 × 10⁴ hailstones per second, each of mass 2.0 g, strike a flat horizontal roof of area 50 m². Each arrives vertically at 15 m s⁻¹ and bounces straight back up at 5.0 m s⁻¹. (a) Calculate the change in momentum of one hailstone. (b) Calculate the mean force on the roof. (c) Calculate the mean pressure on the roof due to the hail. (d) State one way in which this model differs from the impacts of gas molecules on a wall. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '32', 'Pa', false, NULL, false, NULL, '(a) The velocity reverses, so the speeds add: Δp = 0.0020 × (15 + 5.0) = 0.040 kg m s⁻¹. (b) F = 4.0 × 10⁴ × 0.040 = 1600 N. (c) p = 1600 ÷ 50 = 32 Pa. (d) Gas molecules collide elastically and arrive from random directions with a range of speeds, whereas the hailstones lose kinetic energy and all arrive vertically. Mark scheme (5 marks). C1: Δp = m(u + v) because the direction reverses. C1: F = rate × Δp. C1: p = F/A. B1: elastic and random for gas molecules. A1: p = 32.0 Pa.', 5),
('63d12126-9f0f-5875-a92b-69e771a685e6', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 47, 47, 'In a simple model of a gas, 2 molecules move at 100 m s⁻¹, 5 molecules at 300 m s⁻¹ and 3 molecules at 500 m s⁻¹. (a) Calculate the mean speed. (b) Calculate the mean square speed. (c) Calculate the root-mean-square speed. (d) Explain why the r.m.s. speed is greater than the mean speed. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '349.3', 'm s⁻¹', false, NULL, false, NULL, '(a) Mean speed = (2 × 100 + 5 × 300 + 3 × 500) ÷ 10 = 320 m s⁻¹. (b) ⟨c²⟩ = (2 × 100² + 5 × 300² + 3 × 500²) ÷ 10 = 1.22 × 10⁵ m² s⁻². (c) c_rms = √(1.220 × 10⁵) = 349 m s⁻¹. (d) Squaring the speeds gives extra weight to the fastest molecules, so the r.m.s. value is pulled above the mean. Mark scheme (6 marks). C1: mean speed 320 m s⁻¹. C1: sum of squares weighted by numbers. C1: ÷ 10 molecules. C1: square root. B1: squaring weights fast molecules. A1: c_rms = 349 m s⁻¹.', 6),
('556822fa-d2a4-5409-bbbd-08407445be71', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 48, 48, 'The r.m.s. speed of nitrogen molecules at 0 °C is 493 m s⁻¹. (a) Show that the density of nitrogen at 1.01 × 10⁵ Pa and 0 °C is about 1.25 kg m⁻³. (b) A nitrogen molecule has mass 4.65 × 10⁻²⁶ kg. Calculate the number of molecules per cubic metre. (c) The nitrogen is heated at constant volume until the r.m.s. speed is 600 m s⁻¹. Calculate the new pressure. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2.681e25', 'm⁻³', false, NULL, false, NULL, '(a) ρ = 3p/⟨c²⟩ = 3 × 1.01 × 10⁵ ÷ 493² = 1.25 kg m⁻³. (b) n = ρ/m = 1.247 ÷ 4.65 × 10⁻²⁶ = 2.68 × 10²⁵ m⁻³. (c) At constant density p ∝ ⟨c²⟩, so p = 1.01 × 10⁵ × (600 ÷ 493)² = 1.50 × 10⁵ Pa. Mark scheme (5 marks). C1: ρ = 3p/⟨c²⟩. B1: value ≈ 1.25 kg m⁻³ shown. C1: n = ρ/m. M1: p ∝ ⟨c²⟩ at constant volume. A1: n = 2.68 × 10²⁵ m⁻³.', 5),
('29242d12-e773-57dd-bbec-55c22f301558', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 49, 49, 'A vertical cylinder is closed at the top by a frictionless piston of mass 4.0 kg and area 2.0 × 10⁻³ m². Atmospheric pressure is 1.0 × 10⁵ Pa. The gas below the piston has density 1.6 kg m⁻³. (a) Calculate the pressure of the gas when the piston is at rest. (b) Calculate the r.m.s. speed of the gas molecules. (c) The gas is warmed and the piston rises slowly. Explain, in terms of molecular motion, why the piston rises while the gas pressure stays the same. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '473.6', 'm s⁻¹', false, NULL, false, NULL, '(a) p = 1.0 × 10⁵ + 4.0 × 9.81 ÷ 2.0 × 10⁻³ = 1.20 × 10⁵ Pa. (b) ⟨c²⟩ = 3p/ρ, so c_rms = √(3 × 1.196 × 10⁵ ÷ 1.6) = 474 m s⁻¹. (c) Faster molecules hit the piston harder, so it moves up; the gas expands, so the molecules hit each square metre less often, and the pressure returns to the value set by the weight and the atmosphere. Mark scheme (6 marks). C1: pressure from piston = mg/A. C1: add atmospheric pressure. C1: ⟨c²⟩ = 3p/ρ. C1: square root. B1: harder impacts but less frequent as volume rises. A1: c_rms = 474 m s⁻¹.', 6),
('4e7c3c59-9019-5f97-8790-cc337caaef22', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'abc37ad9-553a-497c-9676-00666272de18', 'a-level', '20.2', '9702 coursebook 20.2 · Explaining pressure', 50, 50, 'Air at 1.0 × 10⁵ Pa pushes on an area of 1.0 cm² of a container wall. In a simple model, every molecule (mass 4.8 × 10⁻²⁶ kg) strikes the wall at right angles at 480 m s⁻¹ and rebounds elastically. (a) Calculate the force on the 1.0 cm² area. (b) Calculate the change in momentum of one molecule in a collision. (c) Hence estimate the number of molecular collisions per second on the area. (d) Suggest why this model gives only an estimate. Give only the answer to (c), in s⁻¹.', NULL, 3, 'numeric'::answer_type, '2.17e23', 's⁻¹', false, NULL, false, NULL, '(a) F = pA = 1.0 × 10⁵ × 1.0 × 10⁻⁴ = 10 N. (b) Δp = 2mu = 2 × 4.8 × 10⁻²⁶ × 480 = 4.61 × 10⁻²³ kg m s⁻¹. (c) Collision rate = F ÷ Δp = 10 ÷ 4.608 × 10⁻²³ = 2.17 × 10²³ s⁻¹. (d) Real molecules hit at all angles and with a wide range of speeds, so the true rate differs from this single-speed, head-on estimate. Mark scheme (5 marks). C1: F = pA with 1.0 cm² = 1.0 × 10⁻⁴ m². C1: Δp = 2mu. C1: rate = F ÷ Δp. B1: range of speeds and angles. A1: rate = 2.17 × 10²³ s⁻¹.', 5)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('2ee8ab65-8a6c-57f4-8f61-42868d1939b5', '3f2f6087-0561-53c8-a8f0-f0838d01b2a0', 'Molecules are attracted to the walls', 'A', false, 0),
('18b62ba1-28bf-55a6-8c44-f45f3691f622', '3f2f6087-0561-53c8-a8f0-f0838d01b2a0', 'The weight of the gas presses on the walls', 'B', false, 1),
