('ca4fffb0-fd42-57ba-8ce5-67186f2e4376', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 9, 9, 'How many moles are there in 88 g of carbon dioxide (molar mass 44 g mol⁻¹)?', NULL, 1, 'numeric'::answer_type, '2', 'mol', false, NULL, false, NULL, 'n = m/M = 88 ÷ 44 = 2.0 mol. Mark scheme (1 mark). A1: n = 2.0 mol.', 1),
('ee72986a-279a-5cde-a1b6-4bd93ca8f2ae', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 10, 10, 'Calculate the number of atoms in 0.40 mol of neon. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '2.408e23', NULL, false, NULL, false, NULL, 'N = nN_A = 0.40 × 6.02 × 10²³ = 2.41 × 10²³. Mark scheme (2 marks). C1: N = nN_A. A1: N = 2.41 × 10²³.', 2),
('8b6e4865-834c-5bb8-9eef-3e7f0fac101d', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 11, 11, 'What is the Avogadro constant?', NULL, 1, 'multiple_choice'::answer_type, 'The number of particles in one mole of a substance', NULL, false, NULL, false, NULL, 'N_A = 6.02 × 10²³ mol⁻¹: the number of atoms in exactly 12 g of carbon-12. Mark scheme (1 mark). B1: C (The number of particles in one mole of a substance).', 1),
('b16c87d5-8fdc-5234-ae2b-601394efb7be', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 12, 12, 'One mole of a substance is the amount that contains…', NULL, 1, 'multiple_choice'::answer_type, 'as many particles as there are atoms in 12 g of carbon-12', NULL, false, NULL, false, NULL, 'This is the definition of the mole used in the 9702 course. Mark scheme (1 mark). B1: A (as many particles as there are atoms in 12 g of carbon-12).', 1),
('8b75c0e6-071d-5a2a-a2c2-5360abf0266d', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 13, 13, 'Calculate the mass, in kg, of 2.5 mol of sodium chloride (molar mass 0.0585 kg mol⁻¹).', NULL, 1, 'numeric'::answer_type, '0.1463', 'kg', false, NULL, false, NULL, 'm = nM = 2.5 × 0.0585 = 0.146 kg. Mark scheme (2 marks). C1: m = nM. A1: m = 0.146 kg.', 2),
('bbe01a9c-526b-58b6-80d4-61fb6f71ff00', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 14, 14, 'Which unit is the SI base unit for amount of substance?', NULL, 1, 'multiple_choice'::answer_type, 'mole (mol)', NULL, false, NULL, false, NULL, 'The mole is one of the seven SI base units. Mark scheme (1 mark). B1: D (mole (mol)).', 1),
('077b9c30-0c7b-5b5e-89bc-a6d3abe6676a', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 15, 15, 'A sample contains 1.2 × 10²⁴ atoms of iron. How many moles is this? Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '1.993', 'mol', false, NULL, false, NULL, 'n = N/N_A = 1.2 × 10²⁴ ÷ 6.02 × 10²³ = 1.99 mol. Mark scheme (2 marks). C1: n = N/N_A. A1: n = 1.99 mol.', 2),
('8928d7a6-5669-5cc0-8491-755dc029e480', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 16, 16, 'Calculate the number of molecules in 1.0 kg of water (molar mass 0.018 kg mol⁻¹). Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '3.344e25', NULL, false, NULL, false, NULL, 'n = 1.0 ÷ 0.018 = 55.6 mol, N = 55.56 × 6.02 × 10²³ = 3.34 × 10²⁵. Mark scheme (2 marks). C1: n = m/M, N = nN_A. A1: N = 3.34 × 10²⁵.', 2),
('5fb977eb-e7d0-5877-935e-f542fc930b5a', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 17, 17, 'One mole of helium (4 g) and one mole of oxygen (32 g). Which is the same for both?', NULL, 1, 'multiple_choice'::answer_type, 'The number of molecules', NULL, false, NULL, false, NULL, 'A mole of any substance contains N_A particles. Mark scheme (1 mark). B1: B (The number of molecules).', 1),
('f41a0665-700d-59c1-b743-cdd455ee7b2f', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 18, 18, 'How many moles of copper are in a 0.25 kg block? Molar mass of copper = 0.0635 kg mol⁻¹.', NULL, 1, 'numeric'::answer_type, '3.937', 'mol', false, NULL, false, NULL, 'n = m/M = 0.25 ÷ 0.0635 = 3.94 mol. Mark scheme (2 marks). C1: n = m/M. A1: n = 3.94 mol.', 2),
('01e1a89e-1678-575b-a651-0028525e4fef', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 19, 19, 'What is the molar mass of a substance?', NULL, 1, 'multiple_choice'::answer_type, 'The mass of one mole of it', NULL, false, NULL, false, NULL, 'Molar mass M = m/n, in kg mol⁻¹ (or g mol⁻¹). Mark scheme (1 mark). B1: C (The mass of one mole of it).', 1),
('6c5527a4-9df6-5b3c-ad1f-70223cdac008', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 20, 20, 'Calculate the mass of one carbon-12 atom, in units of 10⁻²⁶ kg. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '1.993', '10⁻²⁶ kg', false, NULL, false, NULL, 'm = M/N_A = 0.012 ÷ 6.02 × 10²³ = 1.99 × 10⁻²⁶ kg. Mark scheme (2 marks). C1: m = M/N_A. A1: m = 1.99 × 10⁻²⁶ kg.', 2),
('da0e7b61-2952-553f-9e86-cf1b56396da8', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 21, 21, 'A balloon contains 3.0 × 10²³ molecules of helium. Calculate the number of moles. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '0.4983', 'mol', false, NULL, false, NULL, 'n = 3.0 × 10²³ ÷ 6.02 × 10²³ = 0.498 mol. Mark scheme (2 marks). C1: n = N/N_A. A1: n = 0.498 mol.', 2),
('5f968867-1118-57fe-9452-98da38733223', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 22, 22, 'Calculate the mass of 1.5 × 10²⁵ molecules of methane (molar mass 0.016 kg mol⁻¹). Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '0.3987', 'kg', false, NULL, false, NULL, 'n = 1.5 × 10²⁵ ÷ 6.02 × 10²³ = 24.9 mol, m = nM = 24.92 × 0.016 = 0.399 kg. Mark scheme (2 marks). C1: n then m = nM. A1: m = 0.399 kg.', 2),
('8edfe31b-6280-55af-8674-984e9f02980c', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 23, 23, 'A gold ring has mass 6.0 g. Gold has molar mass 0.197 kg mol⁻¹. Calculate the number of gold atoms in the ring. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '1.834e22', NULL, false, NULL, false, NULL, 'n = 0.0060 ÷ 0.197 = 0.0305 mol. N = 0.03046 × 6.02 × 10²³ = 1.83 × 10²². Mark scheme (3 marks). C1: mass in kg. C1: n = m/M. C1: N = nN_A.', 3),
('627ebad2-f89c-5351-bde2-56297b2a8f41', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 24, 24, 'A drop of water has a volume of 0.050 cm³. Water has density 1000 kg m⁻³ and molar mass 0.018 kg mol⁻¹. Calculate the number of molecules in the drop. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '1.672e21', NULL, false, NULL, false, NULL, 'm = ρV = 1000 × 0.050 × 10⁻⁶ = 5.0 × 10⁻⁵ kg. n = 5.0 × 10⁻⁵ ÷ 0.018 = 0.00278 mol. N = 0.002778 × 6.02 × 10²³ = 1.67 × 10²¹. Mark scheme (3 marks). C1: m = ρV with cm³ → m³. C1: n = m/M. C1: N = nN_A.', 3),
('976090f8-4ccf-5b89-8ca4-bc714ef8537c', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 25, 25, 'Which statement about one mole of hydrogen gas (H₂) is correct?', NULL, 2, 'multiple_choice'::answer_type, 'It contains 6.02 × 10²³ molecules and 1.20 × 10²⁴ atoms', NULL, false, NULL, false, NULL, 'Each H₂ molecule has 2 atoms; one mole of molecules has mass 2 g. Mark scheme (3 marks). C1: N_A molecules. C1: 2 atoms per molecule. A1: A (It contains 6.02 × 10²³ molecules and 1.20 × 10²⁴ atoms).', 3),
('4abe6940-b7c6-55a4-aed2-19369802762b', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 26, 26, 'Aluminium has density 2700 kg m⁻³ and molar mass 0.027 kg mol⁻¹. Calculate the number of atoms in a 1.0 cm³ cube of aluminium. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '6.02e22', NULL, false, NULL, false, NULL, 'm = 2700 × 1.0 × 10⁻⁶ = 2.7 × 10⁻³ kg. n = 2.7 × 10⁻³ ÷ 0.027 = 0.10 mol. N = 0.10 × 6.02 × 10²³ = 6.02 × 10²². Mark scheme (4 marks). C1: m = ρV. C1: n = m/M. C1: N = nN_A. A1: N = 6.02 × 10²².', 4),
('a5b9008a-5709-5af7-8611-5b706b40bc9b', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 27, 27, 'Calculate the molar mass of a gas, given that 3.0 × 10²⁴ of its molecules have a mass of 0.14 kg. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '0.02809', 'kg mol⁻¹', false, NULL, false, NULL, 'n = 3.0 × 10²⁴ ÷ 6.02 × 10²³ = 4.98 mol. M = m/n = 0.14 ÷ 4.983 = 0.0281 kg mol⁻¹ (probably nitrogen). Mark scheme (3 marks). C1: n = N/N_A. C1: M = m/n. A1: M = 0.0281 kg mol⁻¹.', 3),
('0c167603-f96a-5e7a-82f7-6fd59e4579d4', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 28, 28, 'Why is the Avogadro constant needed to connect the macroscopic gas equation pV = nRT to the microscopic pV = NkT?', NULL, 2, 'multiple_choice'::answer_type, 'Because N = nN_A and k = R/N_A, so nR = Nk', NULL, false, NULL, false, NULL, 'R is per mole, k is per molecule; N_A converts between them. Mark scheme (3 marks). C1: N = nN_A. C1: R = N_A k. A1: D (Because N = nN_A and k = R/N_A, so nR = Nk).', 3),
('bf99a513-b3eb-5a03-9b79-ee7687c0ef42', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 29, 29, 'Use R = 8.31 J K⁻¹ mol⁻¹ and k = 1.38 × 10⁻²³ J K⁻¹ to calculate the Avogadro constant.', NULL, 2, 'numeric'::answer_type, '6.022e23', 'mol⁻¹', false, NULL, false, NULL, 'N_A = R/k = 8.31 ÷ 1.38 × 10⁻²³ = 6.02 × 10²³ mol⁻¹. Mark scheme (3 marks). C1: R = N_A k. C1: rearranged. A1: N_A = 6.02 × 10²³ mol⁻¹.', 3),
('3ae18fd5-8245-5b36-849c-53f16ee8e727', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 30, 30, 'A uranium-235 nucleus has mass 235 u. Calculate the number of nuclei in 1.0 kg of uranium-235, using 1 u = 1.66 × 10⁻²⁷ kg, and compare with 1.0 kg ÷ 0.235 kg mol⁻¹ × N_A. Give the number of nuclei.', NULL, 2, 'numeric'::answer_type, '2.563e24', NULL, false, NULL, false, NULL, 'mass per nucleus = 235 × 1.66 × 10⁻²⁷ = 3.90 × 10⁻²⁵ kg. N = 1.0 ÷ 3.901 × 10⁻²⁵ = 2.56 × 10²⁴. The molar method agrees: 1.0 ÷ 0.235 × 6.02 × 10²³ = 2.56 × 10²⁴. Mark scheme (4 marks). C1: mass per nucleus. C1: N = m/m₁. B1: comparison. A1: N = 2.56 × 10²⁴.', 4),
('03c0f73a-adad-5a08-abe7-12f760c4820d', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 31, 31, 'Which sample contains the greatest number of atoms?', NULL, 2, 'multiple_choice'::answer_type, '1.0 g of hydrogen gas (H₂)', NULL, false, NULL, false, NULL, 'H₂: 0.5 mol of molecules = 1.0 mol of atoms. He: 0.25 mol. O₂: 1/32 mol molecules = 1/16 mol atoms. C: 1/12 mol. Mark scheme (3 marks). C1: moles of atoms in each. C1: hydrogen largest. A1: B (1.0 g of hydrogen gas (H₂)).', 3),
('8d28beb6-6fd7-55b0-b573-0d34e8a02201', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 32, 32, 'A sugar cube (sucrose, molar mass 0.342 kg mol⁻¹) has mass 4.0 g. Calculate the number of sucrose molecules. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '7.041e21', NULL, false, NULL, false, NULL, 'n = 0.0040 ÷ 0.342 = 0.0117 mol. N = 0.01170 × 6.02 × 10²³ = 7.04 × 10²¹. Mark scheme (3 marks). C1: n = m/M. C1: N = nN_A. A1: N = 7.04 × 10²¹.', 3),
('97e2959d-60ec-5b8d-b658-f8b226976f3d', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 33, 33, 'A thin film of oil (molar mass 0.28 kg mol⁻¹, density 900 kg m⁻³) is one molecule thick. A drop of volume 1.0 × 10⁻¹⁰ m³ spreads to an area of 0.050 m². Estimate the size of a molecule, and the number of molecules in the drop. Give the number of molecules. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '1.935e17', NULL, false, NULL, false, NULL, 'Thickness = V/A = 1.0 × 10⁻¹⁰ ÷ 0.050 = 2.0 × 10⁻⁹ m (molecule size). m = 900 × 1.0 × 10⁻¹⁰ = 9.0 × 10⁻⁸ kg, n = 9.0 × 10⁻⁸ ÷ 0.28 = 3.21 × 10⁻⁷ mol, N = 3.214 × 10⁻⁷ × 6.02 × 10²³ = 1.93 × 10¹⁷. Mark scheme (4 marks). C1: thickness = V/A. C1: m = ρV. C1: N = (m/M)N_A. A1: N = 1.93 × 10¹⁷.', 4),
('18fe39eb-1c54-5b7e-887d-67edefafa53c', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 34, 34, 'Two flasks of equal volume at the same temperature and pressure contain hydrogen and carbon dioxide. Which is correct?', NULL, 2, 'multiple_choice'::answer_type, 'They contain the same number of molecules but the CO₂ has 22 times the mass', NULL, false, NULL, false, NULL, 'pV = NkT: same p, V, T means same N. Molar masses 2 and 44 g mol⁻¹ give a mass ratio of 22. Mark scheme (3 marks). C1: same N from pV = NkT. C1: mass ratio 44/2. A1: C (They contain the same number of molecules but the CO₂ has 22 times the mass).', 3),
('0ea6d4de-9b8e-5fd4-b0b4-6927c94b9846', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 35, 35, 'A sample of 1.2 × 10²³ molecules has a mass of 8.0 g. Calculate the mass of one molecule, in units of 10⁻²⁶ kg.', NULL, 2, 'numeric'::answer_type, '6.667', '10⁻²⁶ kg', false, NULL, false, NULL, 'm = 8.0 × 10⁻³ ÷ 1.2 × 10²³ = 6.67 × 10⁻²⁶ kg. Mark scheme (3 marks). C1: mass in kg. C1: ÷ number. A1: m = 6.67 × 10⁻²⁶ kg.', 3),
('050c0eb3-fab7-5b70-b0c1-1062e1303992', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 36, 36, 'One mole of water is about 18 cm³ of liquid but about 22 400 cm³ as steam at 273 K and 1 atm (if it were an ideal gas). What does this show?', NULL, 2, 'multiple_choice'::answer_type, 'The molecules in the gas are on average about 11 times further apart than in the liquid', NULL, false, NULL, false, NULL, 'Volume ratio ≈ 1240, so the spacing ratio ≈ ∛1240 ≈ 11. Mark scheme (4 marks). C1: same number of molecules. C1: volume ratio. C1: cube root. A1: A (The molecules in the gas are on average about 11 times further apart than in the liquid).', 4),
('b50012a9-f8a8-569e-8095-285a7f78f854', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 37, 37, 'A diamond (pure carbon, molar mass 0.012 kg mol⁻¹) has mass 0.20 g (a one-carat stone is 0.20 g). Calculate the number of carbon atoms in the stone. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '1.003e22', NULL, false, NULL, false, NULL, 'n = 2.0 × 10⁻⁴ ÷ 0.012 = 0.0167 mol. N = 0.01667 × 6.02 × 10²³ = 1.00 × 10²². Mark scheme (4 marks). C1: mass in kg. C1: n = m/M. C1: N = nN_A. A1: N = 1.00 × 10²².', 4),
('8ba22aff-5681-5bb6-bf64-c4836fc44d57', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 38, 38, 'How many moles of air are in a classroom 8.0 m × 7.0 m × 3.0 m, if air has density 1.2 kg m⁻³ and molar mass 0.029 kg mol⁻¹?', NULL, 2, 'numeric'::answer_type, '6952', 'mol', false, NULL, false, NULL, 'V = 168 m³, m = 1.2 × 168 = 201.6 kg, n = 201.6 ÷ 0.029 = 6950 mol. Mark scheme (3 marks). C1: volume. C1: m = ρV. C1: n = m/M.', 3),
('cfcdb46a-0d11-5ebf-a5d4-e7d3c9e96bf1', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 39, 39, 'Copper has density 8960 kg m⁻³ and molar mass 0.0635 kg mol⁻¹. Calculate the volume occupied by one mole of copper, in cm³.', NULL, 2, 'numeric'::answer_type, '7.087', 'cm³', false, NULL, false, NULL, 'V = M/ρ = 0.0635 ÷ 8960 = 7.09 × 10⁻⁶ m³. In cm³: 7.087 × 10⁻⁶ × 10⁶ = 7.09. Mark scheme (3 marks). C1: V = M/ρ. C1: m³ → cm³ (× 10⁶). A1: V = 7.09 cm³.', 3),
('16adab79-c7f0-585d-bda8-ea73c06a2bfd', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 40, 40, 'A sample of an unknown gas has mass 2.4 g. At 300 K and 1.0 × 10⁵ Pa it occupies 1.85 × 10⁻³ m³. (a) Calculate the number of moles, using pV = nRT. (b) Calculate the molar mass. (c) Suggest the identity of the gas, and calculate the number of molecules. Give only the answer to (b). Take R = 8.31 J K⁻¹ mol⁻¹ and N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '0.03234', 'kg mol⁻¹', false, NULL, false, NULL, '(a) n = pV/RT = 1.0 × 10⁵ × 1.85 × 10⁻³ ÷ (8.31 × 300) = 0.0742 mol. (b) M = m/n = 0.0024 ÷ 0.07421 = 0.0323 kg mol⁻¹. (c) About 32 g mol⁻¹: oxygen. N = 0.07421 × 6.02 × 10²³ = 4.47 × 10²². Mark scheme (6 marks). C1: n = pV/RT. A1: n. C1: M = m/n. A1: M = 0.0323 kg mol⁻¹. B1: oxygen. B1: N.', 6),
('1287f2ff-05de-54fc-a202-b678a73d6655', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 41, 41, 'A human body contains about 45 kg of water (molar mass 0.018 kg mol⁻¹). (a) Calculate the number of moles of water. (b) Calculate the number of water molecules. (c) Each molecule has 2 hydrogen atoms. Calculate the number of hydrogen atoms. Give only the answer to (c). Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '3.01e27', NULL, false, NULL, false, NULL, '(a) n = 45 ÷ 0.018 = 2500 mol. (b) N = 2500 × 6.02 × 10²³ = 1.51 × 10²⁷. (c) 2 × 1.505 × 10²⁷ = 3.01 × 10²⁷. Mark scheme (5 marks). C1: n = m/M. A1: 2500 mol. C1: N = nN_A. A1: N_H = 3.01 × 10²⁷. A1: × 2.', 5),
('39b53bd5-0585-5cb3-a20a-7c6e4ad89cbe', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 42, 42, 'In an oil-drop experiment, an oil drop of volume 1.2 × 10⁻⁹ m³ spreads on water into a circular film of diameter 0.25 m. The oil has density 870 kg m⁻³ and molar mass 0.26 kg mol⁻¹. (a) Estimate the thickness of the film. (b) Assume the film is one molecule thick and each molecule is a cube. Estimate the volume of one molecule. (c) Estimate the Avogadro constant. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2.046e19', 'mol⁻¹', false, NULL, false, NULL, '(a) t = V/A = 1.2 × 10⁻⁹ ÷ (π × 0.125²) = 2.44 × 10⁻⁸ m. (b) V₁ = t³ = (2.445 × 10⁻⁸)³ = 1.46 × 10⁻²³ m³. (c) Volume of one mole = M/ρ = 0.26 ÷ 870 = 2.99 × 10⁻⁴ m³, so N_A ≈ 2.989 × 10⁻⁴ ÷ 1.461 × 10⁻²³ = 2.05 × 10¹⁹ mol⁻¹ (the right order of magnitude). Mark scheme (6 marks). C1: t = V/A. A1: t. C1: V₁ = t³. C1: molar volume M/ρ. C1: N_A = (M/ρ)/V₁. A1: N_A = 2.05 × 10¹⁹ mol⁻¹.', 6),
('16eb6ae2-1a02-5500-bec5-e5fe421b30a9', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 43, 43, 'A 1.0 m³ container holds a mixture of 2.0 mol of nitrogen (M = 0.028 kg mol⁻¹) and 0.50 mol of oxygen (M = 0.032 kg mol⁻¹). (a) Calculate the total number of molecules. (b) Calculate the total mass. (c) Calculate the mean molar mass of the mixture. Give only the answer to (c). Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '0.0288', 'kg mol⁻¹', false, NULL, false, NULL, '(a) N = 2.5 × 6.02 × 10²³ = 1.51 × 10²⁴. (b) m = 2.0 × 0.028 + 0.50 × 0.032 = 0.072 kg. (c) M = m/n = 0.072 ÷ 2.5 = 0.0288 kg mol⁻¹. Mark scheme (5 marks). A1: N. C1: masses added. A1: m. C1: M = m/n. A1: M = 0.0288 kg mol⁻¹.', 5),
('764d3b9d-a9bf-547a-b947-e171ef6da08a', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 44, 44, 'Silicon has density 2330 kg m⁻³ and molar mass 0.0281 kg mol⁻¹. Its atoms are arranged so that each occupies a volume of 2.0 × 10⁻²⁹ m³. (a) Calculate the number of atoms in 1.0 m³. (b) Calculate the mass of one atom. (c) Hence calculate a value of the Avogadro constant from these data. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '6.03e23', 'mol⁻¹', false, NULL, false, NULL, '(a) 1.0 ÷ 2.0 × 10⁻²⁹ = 5.0 × 10²⁸ atoms. (b) m = 2330 ÷ 5.0 × 10²⁸ = 4.66 × 10⁻²⁶ kg. (c) N_A = M/m = 0.0281 ÷ 4.660 × 10⁻²⁶ = 6.03 × 10²³ mol⁻¹. Mark scheme (6 marks). C1: atoms per m³. A1: 5.0 × 10²⁸. C1: mass of one atom. A1: m. C1: N_A = M/m. A1: N_A = 6.03 × 10²³ mol⁻¹.', 6),
('565c1e3e-e7fc-582a-ae66-f8359d6b8fa9', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 45, 45, 'A reaction produces 0.0050 mol of hydrogen gas (H₂) every second. (a) Calculate the number of molecules produced per second. (b) Calculate the mass produced per minute (M = 0.0020 kg mol⁻¹). (c) Calculate the time to produce 1.0 × 10²⁴ molecules. Give only the answer to (c). Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '332.2', 's', false, NULL, false, NULL, '(a) 0.0050 × 6.02 × 10²³ = 3.01 × 10²¹ s⁻¹. (b) 0.0050 × 60 × 0.0020 = 6.0 × 10⁻⁴ kg. (c) t = 1.0 × 10²⁴ ÷ 3.010 × 10²¹ = 332 s. Mark scheme (5 marks). A1: rate. C1: mass per minute. A1: 6.0 × 10⁻⁴ kg. C1: t = N/rate. A1: t = 332 s.', 5),
('61e00804-cf86-573f-9b6f-f69581e3b30e', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 46, 46, 'Sodium chloride has density 2160 kg m⁻³ and molar mass 0.0585 kg mol⁻¹. Each formula unit, NaCl, is made of one Na⁺ ion and one Cl⁻ ion. (a) Calculate the amount, in moles, of NaCl in 1.0 cm³ of the crystal. (b) Calculate the number of ions in 1.0 cm³. (c) Assuming each ion occupies a small cube, estimate the distance between neighbouring ions. Give only the answer to (c), in nm. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '0.2823 nm', 'nm', false, NULL, false, NULL, '(a) m = 2160 × 1.0 × 10⁻⁶ = 0.00216 kg. n = 0.00216 ÷ 0.0585 = 0.0369 mol. (b) Two ions per formula unit: N = 2 × 0.03692 × 6.02 × 10²³ = 4.45 × 10²². (c) Volume per ion = 1.0 × 10⁻⁶ ÷ 4.446 × 10²² = 2.25 × 10⁻²⁹ m³. Spacing = (2.249 × 10⁻²⁹)^(1/3) = 2.82 × 10⁻¹⁰ m. In nm: 2.823 × 10⁻¹⁰ × 10⁹ = 0.282. Mark scheme (6 marks). C1: m = ρV. C1: n = m/M. M1: two ions per formula unit. C1: volume per ion. C1: cube root. A1: d = 0.282 nm.', 6),
('598c3954-2349-5f3f-9194-01ecf582af2d', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 47, 47, 'A current of 2.0 A passes for 30 minutes through copper sulfate solution, depositing copper on the cathode. Each Cu²⁺ ion needs two electrons to become a copper atom. Copper has molar mass 0.0635 kg mol⁻¹. (a) Calculate the charge carried by one mole of electrons. (b) Calculate the number of copper atoms deposited. (c) Calculate the mass of copper deposited, in mg. Give only the answer to (c). Take N_A = 6.02 × 10²³ mol⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1187 mg', 'mg', false, NULL, false, NULL, '(a) Charge per mole = 6.02 × 10²³ × 1.60 × 10⁻¹⁹ = 9.63 × 10⁴ C. (b) Q = It = 2.0 × 1800 = 3600 C. Electrons = 3600 ÷ 1.60 × 10⁻¹⁹ = 2.25 × 10²². Atoms = 2.25 × 10²² ÷ 2 = 1.13 × 10²². (c) m = 1.125 × 10²² ÷ 6.02 × 10²³ × 0.0635 = 0.00119 kg. In mg: 0.001187 × 10⁶ = 1190. Mark scheme (6 marks). C1: charge per mole = N_A e. C1: Q = It with t in seconds. C1: number of electrons = Q/e. M1: two electrons per atom. C1: m = (N/N_A) × M. A1: m = 1190 mg.', 6),
('6f0e116c-8217-5963-bd01-21050845b006', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 48, 48, 'In an early estimate of the Avogadro constant, a radium source emitted 1.36 × 10¹¹ α-particles per second. Each α-particle collected two electrons and became a helium atom. In one year (3.15 × 10⁷ s), 1.58 × 10⁻⁷ m³ of helium was collected, measured at a temperature and pressure at which one mole of gas occupies 0.0224 m³. (a) Calculate the number of helium atoms collected. (b) Calculate the amount of helium in moles. (c) Hence estimate the Avogadro constant. (d) Suggest one reason why the estimate differs slightly from the accepted value. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '6.074e23', 'mol⁻¹', false, NULL, false, NULL, '(a) N = 1.36 × 10¹¹ × 3.15 × 10⁷ = 4.28 × 10¹⁸. (b) n = 1.58 × 10⁻⁷ ÷ 0.0224 = 7.05 × 10⁻⁶ mol. (c) N_A = N/n = 4.284 × 10¹⁸ ÷ 7.054 × 10⁻⁶ = 6.07 × 10²³ mol⁻¹. (d) A very small volume of gas is hard to measure accurately, and some helium may leak away or stay trapped in the source. Mark scheme (5 marks). C1: N = rate × time. C1: n = V/V_m. M1: N_A = N/n. B1: sensible source of error. A1: N_A = 6.07 × 10²³ mol⁻¹.', 5),
('a9eebe62-35fa-54b4-9552-044014655bce', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 49, 49, 'Gold leaf of thickness 0.10 µm covers an area of 1.0 × 10⁻² m². Gold has density 19 300 kg m⁻³ and molar mass 0.197 kg mol⁻¹. (a) Calculate the mass of the leaf. (b) Calculate the number of gold atoms in the leaf. (c) Assuming each atom occupies a small cube, estimate the diameter of a gold atom. (d) Hence estimate how many layers of atoms make up the thickness of the leaf. Give only the answer to (d). Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '389.3', NULL, false, NULL, false, NULL, '(a) m = 19 300 × 1.0 × 10⁻² × 1.0 × 10⁻⁷ = 1.93 × 10⁻⁵ kg. (b) N = 1.93 × 10⁻⁵ ÷ 0.197 × 6.02 × 10²³ = 5.90 × 10¹⁹. (c) Volume per atom = 0.197 ÷ (19 300 × 6.02 × 10²³) = 1.70 × 10⁻²⁹ m³. d = (1.696 × 10⁻²⁹)^(1/3) = 2.57 × 10⁻¹⁰ m. (d) Layers = 1.0 × 10⁻⁷ ÷ 2.569 × 10⁻¹⁰ = 389. Mark scheme (6 marks). C1: m = ρ × area × thickness. C1: N = (m/M)N_A. C1: volume per atom = M/(ρN_A). C1: d = cube root. C1: layers = thickness ÷ d. A1: layers = 389.', 6),
('f4a6f0a9-e3fa-5010-b424-1466bda9d72e', '468b27d0-3cef-43ee-aeef-09b1a340050f', 'e1c1c48c-6a14-5ab3-b2eb-36b898c80474', 'a-level', '20.3', '9702 coursebook 20.3 · The mole and the Avogadro constant', 50, 50, 'Natural chlorine is 75.8 % chlorine-35 (atomic mass 34.97 u) and 24.2 % chlorine-37 (atomic mass 36.97 u), by number of atoms. (a) Calculate the mean mass of a chlorine atom, in u. (b) Calculate the molar mass of chlorine atoms, using 1 u = 1.66 × 10⁻²⁷ kg. (c) Calculate the number of chlorine-37 atoms in 1.0 g of natural chlorine. Give only the answer to (c). Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '4.112e21', NULL, false, NULL, false, NULL, '(a) Mean mass = 0.758 × 34.97 + 0.242 × 36.97 = 35.45 u. (b) M = 35.45 × 1.66 × 10⁻²⁷ × 6.02 × 10²³ = 0.0354 kg mol⁻¹. (c) Total atoms = 1.0 × 10⁻³ ÷ (35.45 × 1.66 × 10⁻²⁷) = 1.70 × 10²². Atoms of the heavier isotope = 0.242 × 1.699 × 10²² = 4.11 × 10²¹. Mark scheme (5 marks). C1: weighted mean mass. C1: M = mean mass × u × N_A. C1: total atoms in 1.0 g. M1: × 0.242. A1: N = 4.11 × 10²¹.', 5)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('b4a38d46-8ddf-50ec-bd6a-3f2441ea51c9', '8b6e4865-834c-5bb8-9eef-3e7f0fac101d', 'The mass of one mole of a substance', 'A', false, 0),
('9dfe1f87-1fa8-5014-9801-d3e1340deabf', '8b6e4865-834c-5bb8-9eef-3e7f0fac101d', 'The volume of one mole of gas', 'B', false, 1),
('ae6e5a4c-0da4-5ac7-b848-fa9d57c404f1', '8b6e4865-834c-5bb8-9eef-3e7f0fac101d', 'The number of particles in one mole of a substance', 'C', true, 2),
('b00be24b-568d-53d0-9437-155de1dd5e8f', '8b6e4865-834c-5bb8-9eef-3e7f0fac101d', 'The number of moles in 1 kg', 'D', false, 3),
('9cee3885-b346-5287-aff4-16790e620dac', 'b16c87d5-8fdc-5234-ae2b-601394efb7be', 'as many particles as there are atoms in 12 g of carbon-12', 'A', true, 0),
('fc55ee11-a8aa-577a-b4b8-18e30aa84ce6', 'b16c87d5-8fdc-5234-ae2b-601394efb7be', '1 g of particles', 'B', false, 1),
('69c15774-d22b-5370-a46f-5dd392018b56', 'b16c87d5-8fdc-5234-ae2b-601394efb7be', '22.4 litres of particles', 'C', false, 2),
('c5fe339d-65cc-59cf-94df-4d3e18823922', 'b16c87d5-8fdc-5234-ae2b-601394efb7be', '1000 particles', 'D', false, 3),
('a41ab62d-2c0a-58dc-a130-1f52bb3ad8fb', 'bbe01a9c-526b-58b6-80d4-61fb6f71ff00', 'kilogram (kg)', 'A', false, 0),
('a5ad8616-795c-54ee-86a6-4d10c946705c', 'bbe01a9c-526b-58b6-80d4-61fb6f71ff00', 'gram (g)', 'B', false, 1),
('5683a4df-ba28-5021-8161-4de2f95e6a5d', 'bbe01a9c-526b-58b6-80d4-61fb6f71ff00', 'kelvin (K)', 'C', false, 2),
('bf514b00-569f-540b-8510-71c3ac03a78d', 'bbe01a9c-526b-58b6-80d4-61fb6f71ff00', 'mole (mol)', 'D', true, 3),
('3e255e05-500c-5eee-be34-f746cff101b7', '5fb977eb-e7d0-5877-935e-f542fc930b5a', 'The mass', 'A', false, 0),
('84eff841-e943-5c27-9d31-4e6f8880b198', '5fb977eb-e7d0-5877-935e-f542fc930b5a', 'The number of molecules', 'B', true, 1),
('1ad6a617-7574-5fb6-a16c-1f471bdbd73a', '5fb977eb-e7d0-5877-935e-f542fc930b5a', 'The molar mass', 'C', false, 2),
('720fa4be-602d-5b76-aed7-66d9dc437482', '5fb977eb-e7d0-5877-935e-f542fc930b5a', 'The density', 'D', false, 3),
('ce45de73-e1f2-5e43-85c5-b6cb0ed037fa', '01e1a89e-1678-575b-a651-0028525e4fef', 'The mass of one molecule', 'A', false, 0),
('ed86aa00-eb0f-5bf0-8848-295046e51ac2', '01e1a89e-1678-575b-a651-0028525e4fef', 'The number of molecules per kg', 'B', false, 1),
('894d32ee-625d-5e90-93d3-b680e84c3f8e', '01e1a89e-1678-575b-a651-0028525e4fef', 'The mass of one mole of it', 'C', true, 2),
('e820fc8c-38ff-593b-842a-0a879e90c5c8', '01e1a89e-1678-575b-a651-0028525e4fef', 'The mass per unit volume', 'D', false, 3),
('8f2a9889-4c38-54d9-9f4f-72770b87c198', '976090f8-4ccf-5b89-8ca4-bc714ef8537c', 'It contains 6.02 × 10²³ molecules and 1.20 × 10²⁴ atoms', 'A', true, 0),
('df739afc-33c4-51fd-92c3-d8e50ca67b60', '976090f8-4ccf-5b89-8ca4-bc714ef8537c', 'It contains 6.02 × 10²³ atoms', 'B', false, 1),
('5fbc3db6-30cc-553b-9e59-cc38a3abcc98', '976090f8-4ccf-5b89-8ca4-bc714ef8537c', 'It has a mass of 1 g', 'C', false, 2),
('a2537858-9462-568f-80df-6869c8e1cd79', '976090f8-4ccf-5b89-8ca4-bc714ef8537c', 'It contains 3.01 × 10²³ molecules', 'D', false, 3),
('f675ec2f-6a7a-57f1-9e81-994d67ef9f63', '0c167603-f96a-5e7a-82f7-6fd59e4579d4', 'Because R = kN_A²', 'A', false, 0),
('220e0dc5-94e9-582f-bd15-9d08d0ff1ba8', '0c167603-f96a-5e7a-82f7-6fd59e4579d4', 'Because k and R are equal', 'B', false, 1),
('affab581-0663-5612-b449-7fb415654a9a', '0c167603-f96a-5e7a-82f7-6fd59e4579d4', 'Because moles and molecules are the same', 'C', false, 2),
('ec2c132f-70ad-5358-8f29-289607aef28b', '0c167603-f96a-5e7a-82f7-6fd59e4579d4', 'Because N = nN_A and k = R/N_A, so nR = Nk', 'D', true, 3),
('c81758fc-11fe-52cc-9166-c36e902104d9', '03c0f73a-adad-5a08-abe7-12f760c4820d', '1.0 g of helium', 'A', false, 0),
('18fb1ddb-9ac6-5bda-8d14-c49bd78ec72a', '03c0f73a-adad-5a08-abe7-12f760c4820d', '1.0 g of hydrogen gas (H₂)', 'B', true, 1),
('19394742-89d8-545f-b3e9-64abcad2afb8', '03c0f73a-adad-5a08-abe7-12f760c4820d', '1.0 g of oxygen gas', 'C', false, 2),
('0a48ce90-2a40-5a64-a587-af37367b2d6d', '03c0f73a-adad-5a08-abe7-12f760c4820d', '1.0 g of carbon', 'D', false, 3),
('afd9f610-36d6-59c2-b276-57c997526986', '18fe39eb-1c54-5b7e-887d-67edefafa53c', 'They contain the same mass of gas', 'A', false, 0),
('7859b654-c0d9-54c6-b205-bdc58847ceb3', '18fe39eb-1c54-5b7e-887d-67edefafa53c', 'The hydrogen flask has 22 times as many molecules', 'B', false, 1),
('10527259-f64b-5e98-93e7-863343476713', '18fe39eb-1c54-5b7e-887d-67edefafa53c', 'They contain the same number of molecules but the CO₂ has 22 times the mass', 'C', true, 2),
('e3c57c31-788e-5f12-8ba4-1c2507b687aa', '18fe39eb-1c54-5b7e-887d-67edefafa53c', 'The CO₂ molecules move faster', 'D', false, 3),
('bd8a12d8-9e1d-59c2-94f0-09cd5a997d6c', '050c0eb3-fab7-5b70-b0c1-1062e1303992', 'The molecules in the gas are on average about 11 times further apart than in the liquid', 'A', true, 0),
('52356314-c863-5e30-acea-b3244df50630', '050c0eb3-fab7-5b70-b0c1-1062e1303992', 'The molecules in steam are larger', 'B', false, 1),
('f9d8e02e-bf57-5cf0-82cb-3f73f51ea577', '050c0eb3-fab7-5b70-b0c1-1062e1303992', 'Steam contains more molecules per mole', 'C', false, 2),
('517b3aa6-5879-5588-a404-a4c7e0ed4c5a', '050c0eb3-fab7-5b70-b0c1-1062e1303992', 'The molecules in the liquid are about 1000 times further apart', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('d4ced685-68d6-51cb-8403-fb744a837214', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 1, 1, 'Boyle''s law states that for a fixed mass of gas at constant temperature…', NULL, 1, 'multiple_choice'::answer_type, 'the pressure is inversely proportional to the volume', NULL, false, NULL, false, NULL, 'pV = constant when n and T are fixed. Mark scheme (1 mark). B1: C (the pressure is inversely proportional to the volume).', 1),
('32012deb-a62a-58a9-9aaa-75498d37957e', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 2, 2, 'A gas occupies 0.60 m³ at 1.0 × 10⁵ Pa. It is compressed at constant temperature to 0.20 m³. Calculate the new pressure.', NULL, 1, 'numeric'::answer_type, '3e5', 'Pa', false, NULL, false, NULL, 'p₂ = p₁V₁/V₂ = 1.0 × 10⁵ × 0.60 ÷ 0.20 = 3.0 × 10⁵ Pa. Mark scheme (2 marks). C1: p₁V₁ = p₂V₂. A1: p = 3.0 × 10⁵ Pa.', 2),
('60442ce1-cb2c-552b-9e1a-d37843bbae2e', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 3, 3, 'A syringe holds 40 cm³ of air at 100 kPa. The plunger is pushed in slowly until the pressure is 160 kPa. Calculate the new volume.', NULL, 1, 'numeric'::answer_type, '25', 'cm³', false, NULL, false, NULL, 'V₂ = p₁V₁/p₂ = 100 × 40 ÷ 160 = 25 cm³. Mark scheme (2 marks). C1: p₁V₁ = p₂V₂. A1: V = 25 cm³.', 2),
('d403c193-fe10-52bd-b823-e20bc037e50b', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 4, 4, 'Which quantities must be kept constant for Boyle''s law to apply?', NULL, 1, 'multiple_choice'::answer_type, 'The mass of gas and its temperature', NULL, false, NULL, false, NULL, 'Boyle''s law: fixed amount of gas at constant temperature. Mark scheme (1 mark). B1: A (The mass of gas and its temperature).', 1),
('f0f24d46-eb56-5167-b2af-d4f2b614fa38', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 5, 5, 'A graph of p against 1/V for a gas obeying Boyle''s law is…', NULL, 1, 'multiple_choice'::answer_type, 'a straight line through the origin', NULL, false, NULL, false, NULL, 'p = constant × (1/V): proportional, so a line through the origin. Mark scheme (1 mark). B1: D (a straight line through the origin).', 1),
('d8a5e694-601e-5f39-8941-ec53dc969b76', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 6, 6, 'A bubble of air has a volume of 2.0 cm³ at the bottom of a lake, where the pressure is 3.0 × 10⁵ Pa. What is its volume just below the surface, where the pressure is 1.0 × 10⁵ Pa? (Assume constant temperature.)', NULL, 1, 'numeric'::answer_type, '6', 'cm³', false, NULL, false, NULL, 'V₂ = p₁V₁/p₂ = 3.0 × 10⁵ × 2.0 ÷ 1.0 × 10⁵ = 6.0 cm³. Mark scheme (2 marks). C1: p₁V₁ = p₂V₂. A1: V = 6.0 cm³.', 2),
('7540c4fc-316b-5a07-8e57-ec103623b112', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 7, 7, 'A graph of p against V for a gas at constant temperature is…', NULL, 1, 'multiple_choice'::answer_type, 'a curve (hyperbola) with p decreasing as V increases', NULL, false, NULL, false, NULL, 'p ∝ 1/V gives a hyperbola, called an isothermal. Mark scheme (1 mark). B1: B (a curve (hyperbola) with p decreasing as V increases).', 1),
('34aaac7d-f503-5506-bd1d-3ff6b092c8be', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 8, 8, 'A diver''s lungs hold 5.5 litres of air at 2.0 × 10⁵ Pa at depth. If the diver rose without exhaling, what volume would the air expand to at 1.0 × 10⁵ Pa (same temperature)?', NULL, 1, 'numeric'::answer_type, '11', 'litres', false, NULL, false, NULL, 'V₂ = p₁V₁/p₂ = 2.0 × 10⁵ × 5.5 ÷ 1.0 × 10⁵ = 11 litres — which is why divers must breathe out as they rise. Mark scheme (2 marks). C1: p₁V₁ = p₂V₂. A1: V = 11 litres.', 2),
('99eb4a66-df05-5912-a2ba-7bf2883ec5a5', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 9, 9, 'In a Boyle''s law experiment, why is the pump moved slowly?', NULL, 1, 'multiple_choice'::answer_type, 'So the gas stays at the same temperature (heat can flow in or out)', NULL, false, NULL, false, NULL, 'Fast compression heats the gas; slow changes keep it isothermal. Mark scheme (1 mark). B1: C (So the gas stays at the same temperature (heat can flow in or out)).', 1),
('d075bb58-9976-589b-ba91-02d7afa8e612', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 10, 10, 'A gas has pV = 2400 J at a certain temperature. What is its pressure when its volume is 0.030 m³?', NULL, 1, 'numeric'::answer_type, '80000', 'Pa', false, NULL, false, NULL, 'p = 2400 ÷ 0.030 = 8.0 × 10⁴ Pa. Mark scheme (2 marks). C1: p = constant/V. A1: p = 8.0 × 10⁴ Pa.', 2),
('5454b967-60e3-5b2a-a0bc-d89116dcfa80', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 11, 11, 'The volume of a fixed mass of gas at constant temperature is doubled. What happens to its pressure?', NULL, 1, 'multiple_choice'::answer_type, 'It halves', NULL, false, NULL, false, NULL, 'At constant temperature pV is constant, so p ∝ 1/V: doubling V halves p. Mark scheme (1 mark). B1: A (It halves).', 1),
('74aad276-b229-5c48-b7d8-14aac701fd65', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 12, 12, 'A tyre pump cylinder contains 120 cm³ of air at 1.0 × 10⁵ Pa. Calculate the pressure when the air is squeezed into 40 cm³ at constant temperature.', NULL, 1, 'numeric'::answer_type, '3e5', 'Pa', false, NULL, false, NULL, 'p₂ = 1.0 × 10⁵ × 120 ÷ 40 = 3.0 × 10⁵ Pa. Mark scheme (2 marks). C1: p₁V₁ = p₂V₂. A1: p = 3.0 × 10⁵ Pa.', 2),
('d7b8d017-36fc-5fb0-8c17-7b333113971d', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 13, 13, 'Which units can be used for V in p₁V₁ = p₂V₂?', NULL, 1, 'multiple_choice'::answer_type, 'Any volume unit, as long as both volumes use the same unit', NULL, false, NULL, false, NULL, 'The units cancel in the ratio V₁/V₂. Mark scheme (1 mark). B1: D (Any volume unit, as long as both volumes use the same unit).', 1),
('8e40fa3d-a0b4-5398-b4ca-9a1f56165528', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 14, 14, 'A sealed syringe of air at 101 kPa is pulled out from 15 cm³ to 45 cm³ at constant temperature. Calculate the new pressure in kPa.', NULL, 1, 'numeric'::answer_type, '33.67 kPa', 'kPa', false, NULL, false, NULL, 'p₂ = 101 × 15 ÷ 45 = 33.7 kPa. Mark scheme (2 marks). C1: p₁V₁ = p₂V₂. A1: p = 33.7 kPa.', 2),
('4464fc8b-0d76-5b67-9183-ad233b470376', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 15, 15, 'For a gas obeying Boyle''s law, what is constant?', NULL, 1, 'multiple_choice'::answer_type, 'The product of pressure and volume', NULL, false, NULL, false, NULL, 'pV = constant at fixed n and T. Mark scheme (1 mark). B1: B (The product of pressure and volume).', 1),
('f9e0bd71-55e1-5423-a0dc-caa438012027', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 16, 16, 'An aerosol can holds 0.40 litres of gas at 4.0 × 10⁵ Pa. What volume would this gas occupy at 1.0 × 10⁵ Pa at the same temperature?', NULL, 1, 'numeric'::answer_type, '1.6', 'litres', false, NULL, false, NULL, 'V₂ = 4.0 × 10⁵ × 0.40 ÷ 1.0 × 10⁵ = 1.6 litres. Mark scheme (2 marks). C1: p₁V₁ = p₂V₂. A1: V = 1.6 litres.', 2),
('4710e8a2-b834-5055-bb4f-eaca270816a0', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 17, 17, 'Using the kinetic model, why does the pressure of a gas increase when it is compressed at constant temperature?', NULL, 1, 'multiple_choice'::answer_type, 'The molecules hit each unit area of the walls more often', NULL, false, NULL, false, NULL, 'Same speeds, higher number density, so more collisions per second per unit area. Mark scheme (1 mark). B1: C (The molecules hit each unit area of the walls more often).', 1),
('40796a21-ee77-52d9-9e81-62217ad3813f', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 18, 18, 'A weather balloon holds 12 m³ of helium at 100 kPa on the ground. At high altitude the pressure is 30 kPa. Assuming the temperature is unchanged, calculate its volume there.', NULL, 1, 'numeric'::answer_type, '40', 'm³', false, NULL, false, NULL, 'V₂ = 100 × 12 ÷ 30 = 40 m³. Mark scheme (2 marks). C1: p₁V₁ = p₂V₂. A1: V = 40 m³.', 2),
('fd095e58-7a93-5680-b9bc-36c76ad23e22', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 19, 19, 'A gas at 1.2 × 10⁵ Pa occupies 3.0 litres. Calculate the change in volume when the pressure is increased to 1.8 × 10⁵ Pa at constant temperature.', NULL, 2, 'numeric'::answer_type, '1', 'litres', false, NULL, false, NULL, 'V₂ = 3.0 × 1.2 ÷ 1.8 = 2.0 litres, so the volume decreases by 3.0 − 2.0 = 1.0 litre. Mark scheme (3 marks). C1: p₁V₁ = p₂V₂. C1: V₂. C1: change.', 3),
('b9ef15b2-3af3-5d49-b7cb-9e74e0875cd7', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 20, 20, 'A bubble rises from the bottom of a 15 m deep lake to the surface. At the surface the pressure is 1.0 × 10⁵ Pa; at the bottom it is 1.0 × 10⁵ + ρgh. The bubble''s volume at the bottom is 1.5 cm³. Calculate its volume at the surface (ρ = 1000 kg m⁻³, constant temperature). Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '3.707', 'cm³', false, NULL, false, NULL, 'p_bottom = 1.0 × 10⁵ + 1000 × 9.81 × 15 = 2.47 × 10⁵ Pa. V = 1.5 × 2.472 × 10⁵ ÷ 1.0 × 10⁵ = 3.71 cm³. Mark scheme (4 marks). C1: p = p₀ + ρgh. C1: p₁V₁ = p₂V₂. C1: substitution. A1: V = 3.71 cm³.', 4),
('cfb058c1-51dd-5ed7-bd45-c33e9c429fb0', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 21, 21, 'A student plots p against 1/V for air in a syringe and gets a straight line that does not quite pass through the origin. Which is the most likely reason?', NULL, 2, 'multiple_choice'::answer_type, 'The air in the connecting tube was not included in V', NULL, false, NULL, false, NULL, 'A systematic error in V (a small unmeasured extra volume) shifts the line. Mark scheme (3 marks). C1: systematic error. C1: unmeasured volume. A1: A (The air in the connecting tube was not included in V).', 3),
('b447b2f5-22b4-56a5-9900-e5fb01c0c41c', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 22, 22, 'A cylinder of compressed air has volume 12 litres at 2.0 × 10⁷ Pa. How many 2.0-litre balloons can it fill at 1.0 × 10⁵ Pa, at constant temperature? (The cylinder keeps 12 litres at 1.0 × 10⁵ Pa when it is "empty".)', NULL, 2, 'numeric'::answer_type, '1194', NULL, false, 0.01, false, NULL, 'Total volume at 1.0 × 10⁵ Pa = 12 × 2.0 × 10⁷ ÷ 1.0 × 10⁵ = 2400 litres. Usable = 2400 − 12 = 2388 litres. Balloons = 2388 ÷ 2.0 = 1194. Mark scheme (3 marks). C1: total volume at atmospheric pressure. C1: subtract residual 12 litres. C1: ÷ 2.0.', 3),
('f9ae6d31-0a52-5d91-8e35-1ba42fcda29f', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 23, 23, 'On a p–V graph, two isothermals (Boyle''s-law curves) are drawn for the same gas. Which is at the higher temperature?', NULL, 2, 'multiple_choice'::answer_type, 'The one further from the origin', NULL, false, NULL, false, NULL, 'pV = nRT: a higher T gives a larger pV, so the curve is further out. Mark scheme (3 marks). C1: pV ∝ T. C1: curve further out. A1: D (The one further from the origin).', 3),
('fa290ef7-8046-50f9-8f84-2d84cc7dfa1c', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 24, 24, 'A gas is held in a 25 cm long tube by a column of mercury. At atmospheric pressure (76 cm Hg) the trapped air column is 20 cm long. The tube is turned so the extra mercury pressure on the air is 15 cm Hg. Calculate the new length of the air column (constant temperature, uniform tube).', NULL, 2, 'numeric'::answer_type, '16.7 cm', 'cm', false, NULL, false, NULL, 'p₁ = 76 cm Hg, p₂ = 76 + 15 = 91 cm Hg. L₂ = L₁p₁/p₂ = 20 × 76 ÷ 91 = 16.7 cm. Mark scheme (4 marks). C1: total pressure. C1: V ∝ L for uniform tube. C1: p₁L₁ = p₂L₂. A1: L = 16.7 cm.', 4),
('9afb0725-8eda-58e1-9f01-a1ede5eedd3c', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 25, 25, 'In a Boyle''s-law experiment, pV for air is found to be 101 J at p = 1.01 × 10⁵ Pa. Calculate the volume when p = 2.50 × 10⁵ Pa.', NULL, 2, 'numeric'::answer_type, '4.04e-4', 'm³', false, NULL, false, NULL, 'V = 101 ÷ 2.50 × 10⁵ = 4.04 × 10⁻⁴ m³. Mark scheme (3 marks). C1: pV = constant. C1: V = constant/p. A1: V = 4.04 × 10⁻⁴ m³.', 3),
('6e0d5c72-1240-5e8d-89b5-6e4b56a7bd5f', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 26, 26, 'A gas is compressed rapidly from 1.0 litre to 0.50 litre and its pressure is measured immediately. The pressure is more than double the starting pressure. Why?', NULL, 2, 'multiple_choice'::answer_type, 'The fast compression heated the gas, so Boyle''s law (constant temperature) did not apply', NULL, false, NULL, false, NULL, 'Work done on the gas raised its temperature; pV increased. Mark scheme (4 marks). C1: rapid compression heats. C1: not isothermal. C1: pV increases. A1: B (The fast compression heated the gas, so Boyle''s law (constant temperature) did not apply).', 4),
('37c63d50-98f5-5a62-9119-a8f49af1be49', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 27, 27, 'A balloon has volume 4.0 litres at sea level (101 kPa). At the top of a mountain it has expanded to 5.5 litres at the same temperature. Calculate the air pressure at the top.', NULL, 2, 'numeric'::answer_type, '73.45 kPa', 'kPa', false, NULL, false, NULL, 'p₂ = 101 × 4.0 ÷ 5.5 = 73.5 kPa. Mark scheme (3 marks). C1: p₁V₁ = p₂V₂. C1: substitution. A1: p = 73.5 kPa.', 3),
('5482d1a4-756d-5381-9b13-173008862ad8', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 28, 28, 'A gas in a flexible container obeys Boyle''s law. When the pressure rises by 25 %, by what percentage does the volume fall?', NULL, 2, 'numeric'::answer_type, '20', '%', false, NULL, false, NULL, 'V₂/V₁ = 1/1.25 = 0.80, so the volume falls by (1 − 0.80) × 100 = 20 %. Mark scheme (3 marks). C1: V ∝ 1/p. C1: percentage. A1: decrease = 20%.', 3),
('2307df99-7f19-590a-b808-8141f1722a7b', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 29, 29, 'Why does Boyle''s law fail for real gases at very high pressure?', NULL, 2, 'multiple_choice'::answer_type, 'The molecules'' own volume and the attractive forces between them become significant', NULL, false, NULL, false, NULL, 'At high density the ideal-gas assumptions no longer hold. Mark scheme (3 marks). C1: molecular volume. C1: intermolecular forces. A1: C (The molecules'' own volume and the attractive forces between them become significant).', 3),
('0d2e8ec0-1030-5f33-9529-99487e062525', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 30, 30, 'A bicycle pump has a 30 cm long barrel. The outlet valve opens when the pressure inside reaches 4.0 × 10⁵ Pa. Starting with air at 1.0 × 10⁵ Pa in the full barrel, how far must the piston be pushed before air enters the tyre? (Assume constant temperature.)', NULL, 2, 'numeric'::answer_type, '22.5 cm', 'cm', false, NULL, false, NULL, 'L₂ = 30 × 1.0 × 10⁵ ÷ 4.0 × 10⁵ = 7.5 cm, so the piston moves 30 − 7.5 = 22.5 cm. Mark scheme (4 marks). C1: p₁L₁ = p₂L₂. C1: L₂. C1: distance moved. A1: d = 22.5 cm.', 4),
('f8b6a9f3-f8c3-58ab-9bc0-02e4eb195be5', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 31, 31, 'A sealed bag of crisps has 300 cm³ of air at 101 kPa. It is taken on a plane where the cabin pressure is 75 kPa. Calculate the new volume of air, at constant temperature.', NULL, 2, 'numeric'::answer_type, '404', 'cm³', false, NULL, false, NULL, 'V₂ = 300 × 101 ÷ 75 = 404 cm³ — the bag puffs up. Mark scheme (3 marks). C1: p₁V₁ = p₂V₂. C1: substitution. A1: V = 404 cm³.', 3),
('99ef03bf-186f-5738-ac68-0ec113e6b2cf', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 32, 32, 'A gas obeys Boyle''s law. Its pressure is plotted against volume and also against 1/V. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The p–1/V graph is linear through the origin, which is easier to test than the p–V curve', NULL, false, NULL, false, NULL, 'p = k(1/V): a straight line through the origin with gradient k = pV. Mark scheme (3 marks). C1: p ∝ 1/V. C1: straight line test. A1: A (The p–1/V graph is linear through the origin, which is easier to test than the p–V curve).', 3),
('94c4bc14-e8b9-59d8-b0b8-5a4206823f89', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 33, 33, 'Two flasks are joined by a closed tap. Flask A (2.0 litres) holds gas at 3.0 × 10⁵ Pa; flask B (3.0 litres) is evacuated. The tap is opened. Calculate the final pressure, at constant temperature.', NULL, 2, 'numeric'::answer_type, '1.2e5', 'Pa', false, NULL, false, NULL, 'p₂ = p₁V₁/V₂ = 3.0 × 10⁵ × 2.0 ÷ (2.0 + 3.0) = 1.2 × 10⁵ Pa. Mark scheme (4 marks). C1: total volume 5.0 litres. C1: p₁V₁ = p₂V₂. C1: substitution. A1: p = 1.2 × 10⁵ Pa.', 4),
('ac847238-9e39-516e-89c0-4e28e4450eda', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 34, 34, 'At constant temperature, pV for a sample of gas is 3600 J. Calculate the pressure when the volume is 4.5 litres.', NULL, 2, 'numeric'::answer_type, '8e5', 'Pa', false, NULL, false, NULL, 'V = 4.5 × 10⁻³ m³. p = 3600 ÷ 4.5 × 10⁻³ = 8.0 × 10⁵ Pa. Mark scheme (3 marks). C1: litres to m³. C1: p = constant/V. A1: p = 8.0 × 10⁵ Pa.', 3),
('c4616bdf-18a9-5cfa-a1a2-66df8f716319', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 35, 35, 'A syringe of gas is compressed to a quarter of its volume at constant temperature. What happens to the number of molecules per unit volume and to the mean kinetic energy?', NULL, 2, 'multiple_choice'::answer_type, 'Number per unit volume ×4; mean kinetic energy unchanged', NULL, false, NULL, false, NULL, 'Same molecules in ¼ the volume, same temperature. Mark scheme (3 marks). C1: density ×4. C1: T unchanged. A1: D (Number per unit volume ×4; mean kinetic energy unchanged).', 3),
('1a922a47-edeb-5964-9152-fdd05babe01e', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 36, 36, 'A gas cylinder at 1.5 × 10⁷ Pa supplies gas to a welding torch at 2.0 × 10⁵ Pa. The cylinder volume is 0.050 m³. Calculate the volume of gas at the torch pressure that can be supplied before the cylinder pressure falls to 2.0 × 10⁵ Pa (constant temperature).', NULL, 2, 'numeric'::answer_type, '3.7', 'm³', false, NULL, false, NULL, 'At 2.0 × 10⁵ Pa the gas would occupy 0.050 × 1.5 × 10⁷ ÷ 2.0 × 10⁵ = 3.75 m³. The cylinder keeps 0.050 m³, so 3.75 − 0.050 = 3.70 m³ is supplied. Mark scheme (4 marks). C1: p₁V₁ = p₂V₂. C1: subtract cylinder volume. C1: substitution. A1: V = 3.70 m³.', 4),
('a19ddb6e-9c01-502c-b1d4-322eae16a4a4', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 37, 37, 'A student records: V = 20 cm³, p = 150 kPa; V = 30 cm³, p = 100 kPa; V = 40 cm³, p = 75 kPa. Show that the data obey Boyle''s law and find the pressure at V = 60 cm³.', NULL, 2, 'numeric'::answer_type, '50 kPa', 'kPa', false, NULL, false, NULL, 'pV = 20 × 150 = 30 × 100 = 40 × 75 = 3000 kPa cm³: constant. At 60 cm³, p = 3000 ÷ 60 = 50 kPa. Mark scheme (3 marks). C1: pV for each. B1: constant. C1: p = 3000/60.', 3),
('4141709c-5d47-5a9e-9c2f-4eb1059ff975', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 38, 38, 'A diver at a depth where the pressure is 3.5 × 10⁵ Pa breathes out a bubble of volume 3.0 cm³. The water temperature is constant. (a) Calculate the bubble''s volume at the surface (1.0 × 10⁵ Pa). (b) Calculate its volume halfway up, where the pressure is 2.25 × 10⁵ Pa. (c) Explain, using the kinetic model, why the bubble grows. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '10.5', 'cm³', false, NULL, false, NULL, '(a) V = 3.5 × 10⁵ × 3.0 ÷ 1.0 × 10⁵ = 10.5 cm³. (b) V = 3.5 × 10⁵ × 3.0 ÷ 2.25 × 10⁵ = 4.67 cm³. (c) The water pressure outside falls; the gas expands until its molecules hit the walls less often, so its pressure matches the lower outside pressure. Mark scheme (5 marks). C1: p₁V₁ = p₂V₂. A1: 10.5 cm³. A1: 4.67 cm³. B1: lower outside pressure. B1: fewer collisions per area.', 5),
('7f8ddec1-8ff0-57f2-944d-65db03afeb89', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 39, 39, 'A student tests Boyle''s law with a syringe connected to a pressure gauge by a tube of internal volume 2.0 cm³ (not included in the syringe reading). Syringe readings: 18.0 cm³ at 100 kPa and 8.0 cm³ at p₂. (a) Calculate p₂ if the tube volume is ignored. (b) Calculate p₂ allowing for the tube. (c) Explain which is correct and the effect on a p–1/V graph. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '200 kPa', 'kPa', false, NULL, false, NULL, '(a) p₂ = 100 × 18.0 ÷ 8.0 = 225 kPa. (b) Total volumes 20.0 and 10.0 cm³: p₂ = 100 × 20.0 ÷ 10.0 = 200 kPa. (c) (b) is correct; ignoring the tube gives a straight p–1/V line that does not pass through the origin. Mark scheme (6 marks). C1: ignoring tube. A1: 225 kPa. C1: total volumes. A1: 200 kPa. B1: (b) correct. B1: line misses origin.', 6),
('48b6d593-b32c-57fd-8ca6-4d73c87295f1', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 40, 40, 'A sealed glass bulb of volume 50 cm³ contains air at 1.0 × 10⁵ Pa. It is connected via a tap to an evacuated bulb. When the tap is opened the pressure falls to 3.8 × 10⁴ Pa at the same temperature. (a) Calculate the total volume. (b) Calculate the volume of the second bulb. (c) Explain why the temperature might drop slightly at first. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '81.58', 'cm³', false, NULL, false, NULL, '(a) V = 50 × 1.0 × 10⁵ ÷ 3.8 × 10⁴ = 132 cm³. (b) V₂ = 131.6 − 50 = 81.6 cm³. (c) If the expansion is fast, the gas does work pushing gas into the other bulb and briefly cools before reaching equilibrium with the glass. Mark scheme (5 marks). C1: p₁V₁ = p₂V₂. A1: total V. C1: subtract. A1: V = 81.6 cm³. B1: rapid expansion cools.', 5),
('12d81a0e-064d-5a69-88b4-938d9bf604e2', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 41, 41, 'Data for air at constant temperature: V/cm³ = 10, 15, 20, 25, 30; p/kPa = 300, 200, 150, 120, 100. (a) Calculate pV for each reading and comment. (b) Describe the graph of p against 1/V, giving its gradient with units. (c) Calculate the number of moles of air at 293 K. Give only the answer to (c). Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '0.001232', 'mol', false, NULL, false, NULL, '(a) pV = 3000 kPa cm³ for every reading: Boyle''s law is obeyed. (b) A straight line through the origin with gradient pV = 3000 kPa cm³ = 3.0 J. (c) n = pV/RT = 3.0 ÷ (8.31 × 293) = 1.23 × 10⁻³ mol. Mark scheme (6 marks). M1: pV for each. A1: constant 3000 kPa cm³. B1: straight line through origin. C1: gradient = pV = 3.0 J. C1: n = pV/RT. A1: n = 0.00123 mol.', 6),
('45ac19ee-2686-5aa8-b69e-60b2b4c06743', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 42, 42, 'A car tyre contains 0.012 m³ of air at 3.2 × 10⁵ Pa. A puncture lets air leak out slowly at constant temperature until the pressure is 1.0 × 10⁵ Pa (atmospheric). (a) Calculate the volume the original air would occupy at 1.0 × 10⁵ Pa. (b) Calculate the volume of air (at atmospheric pressure) that leaked out. (c) Calculate the fraction of the original air that escaped. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.6875', NULL, false, NULL, false, NULL, '(a) V = 0.012 × 3.2 × 10⁵ ÷ 1.0 × 10⁵ = 0.0384 m³. (b) The tyre keeps 0.012 m³, so 0.0384 − 0.012 = 0.0264 m³ leaked. (c) fraction = 0.0264 ÷ 0.0384 = 0.6875. Mark scheme (5 marks). C1: Boyle''s law. A1: 0.0384 m³. A1: 0.0264 m³. C1: fraction. A1: 0.69.', 5),
('8d09d22f-080c-577b-a056-120087b8f0cc', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 43, 43, 'A vertical cylinder holds air below a frictionless piston of mass 10 kg and area 5.0 × 10⁻³ m². Atmospheric pressure is 1.0 × 10⁵ Pa. The air column is 20 cm high. A 5.0 kg mass is placed on the piston, at constant temperature. (a) Calculate the initial pressure of the trapped air. (b) Calculate the new pressure. (c) Calculate the new height of the air column. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '18.48 cm', 'cm', false, NULL, false, NULL, '(a) p₁ = 1.0 × 10⁵ + 10 × 9.81 ÷ 5.0 × 10⁻³ = 1.20 × 10⁵ Pa. (b) p₂ = 1.0 × 10⁵ + 15 × 9.81 ÷ 5.0 × 10⁻³ = 1.29 × 10⁵ Pa. (c) h₂ = h₁p₁/p₂ = 20 × 1.196 × 10⁵ ÷ 1.294 × 10⁵ = 18.5 cm. Mark scheme (6 marks). C1: p = p₀ + mg/A. A1: p₁. A1: p₂. M1: p₁h₁ = p₂h₂. C1: substitution. A1: h = 18.5 cm.', 6),
('cb16b347-8415-507d-a77a-6087db433878', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 44, 44, 'Explain why a weather balloon, filled with helium at ground level, bursts at high altitude. A balloon holds 6.0 m³ at 100 kPa and 290 K; it bursts at 18 m³. Assuming the temperature stays at 290 K: (a) calculate the pressure at bursting; (b) the air temperature at altitude is really 220 K. Use pV/T = constant to calculate the pressure at bursting at 220 K. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '25.29 kPa', 'kPa', false, NULL, false, NULL, '(a) p = 100 × 6.0 ÷ 18 = 33.3 kPa. (b) p₂ = p₁V₁T₂/(T₁V₂) = 100 × 6.0 × 220 ÷ (290 × 18) = 25.3 kPa — the balloon must rise even higher, to a lower pressure, before it bursts. As the outside pressure falls the helium expands until the rubber can stretch no further. Mark scheme (5 marks). C1: Boyle''s law. A1: 33.3 kPa. C1: pV/T constant. A1: p = 25.3 kPa. B1: expansion until burst.', 5),
('bf312ef2-aa97-52af-a490-7a7058a3f08e', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 45, 45, 'A cylinder of gas has a pressure gauge reading 2.0 × 10⁶ Pa (absolute). It supplies 1.5 litres per minute of gas at 1.0 × 10⁵ Pa to a patient. The cylinder volume is 10 litres and the gas temperature is constant. (a) Calculate the volume of gas available at 1.0 × 10⁵ Pa, leaving the cylinder at 1.0 × 10⁵ Pa. (b) Calculate how long the cylinder lasts. (c) Calculate the cylinder pressure after 1.0 hour. Give only the answer to (b), in minutes.', NULL, 3, 'numeric'::answer_type, '126.7', 'minutes', false, NULL, false, NULL, '(a) V = 10 × 2.0 × 10⁶ ÷ 1.0 × 10⁵ − 10 = 200 − 10 = 190 litres. (b) t = 190 ÷ 1.5 = 127 minutes. (c) After 60 min, 90 litres used: 200 − 90 = 110 litres-at-1 atm remain in 10 litres, so p = 1.0 × 10⁵ × 110 ÷ 10 = 1.1 × 10⁶ Pa. Mark scheme (6 marks). C1: Boyle''s law. C1: subtract residual. A1: 190 litres. C1: t = V/rate. A1: t = 127 minutes. B1: pressure after 1 h.', 6),
('63806cc0-bf3c-5d1a-9cc6-0866413c9a2a', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 46, 46, 'A U-tube manometer with water is used to measure the pressure of a gas being compressed in a syringe. Initially the levels are equal (gas at 101 kPa) and the gas volume is 50 cm³. After compression the water levels differ by 34 cm. (a) Calculate the pressure difference, ρgh. (b) Calculate the new gas pressure. (c) Calculate the new volume at constant temperature. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '48.4', 'cm³', false, NULL, false, NULL, '(a) Δp = 1000 × 9.81 × 0.34 = 3340 Pa. (b) p = 101000 + 3335 = 1.04 × 10⁵ Pa. (c) V = 50 × 101000 ÷ 1.04335 × 10⁵ = 48.4 cm³. Mark scheme (5 marks). C1: Δp = ρgh. A1: Δp. A1: p. C1: Boyle''s law. A1: V = 48.4 cm³.', 5),
('b242fb83-0558-5ffc-ae0f-c1fad8469213', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 47, 47, 'An explorer''s sealed food container holds 1.5 litres of air at 1.01 × 10⁵ Pa at sea level. (a) At the top of a mountain the air pressure is 6.0 × 10⁴ Pa. Calculate the resultant force on the 0.020 m² lid due to the pressure difference, assuming the volume stays fixed. (b) If the lid were free to rise, calculate the volume the air would expand to (constant temperature). Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '820', 'N', false, NULL, false, NULL, '(a) Δp = 1.01 × 10⁵ − 6.0 × 10⁴ = 4.1 × 10⁴ Pa, F = ΔpA = 4.1 × 10⁴ × 0.020 = 820 N (pushing the lid outwards). (b) V = 1.5 × 1.01 × 10⁵ ÷ 6.0 × 10⁴ = 2.5 litres. Mark scheme (6 marks). C1: pressure difference. C1: F = ΔpA. A1: F. B1: direction. C1: Boyle''s law. A1: F = 820 N.', 6),
('3bbab1e1-8560-5ef9-ad44-f486cb883517', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 48, 48, 'A diving bell is a cylinder of height 3.0 m, closed at the top and open at the bottom. It is full of air at 1.0 × 10⁵ Pa when its lower edge touches the sea surface. It is lowered slowly until the sea water has risen 1.0 m inside it. The temperature of the trapped air stays constant. Sea water has density 1030 kg m⁻³ and atmospheric pressure is 1.0 × 10⁵ Pa. (a) Calculate the pressure of the trapped air. (b) Calculate the depth of the water surface inside the bell below the sea surface. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '4.948', 'm', false, NULL, false, NULL, '(a) The bell has a uniform cross-section, so V ∝ length of the air column: p₂ = 1.0 × 10⁵ × 3.0 ÷ 2.0 = 1.5 × 10⁵ Pa. (b) p₂ = p₀ + ρgh, so h = (1.5 × 10⁵ − 1.0 × 10⁵) ÷ (1030 × 9.81) = 4.95 m. Mark scheme (5 marks). C1: Boyle''s law with V ∝ air-column length. C1: p₂ = 1.5 × 10⁵ Pa. C1: p = p₀ + ρgh. C1: rearranged for h. A1: h = 4.95 m.', 5),
('e1bda250-74ed-5e9f-aa90-70a14f21214d', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 49, 49, 'A car tyre has a fixed volume of 2000 cm³ and contains air at 1.0 × 10⁵ Pa. A pump delivers 150 cm³ of atmospheric air (1.0 × 10⁵ Pa) with each stroke. Assume the temperature stays constant. (a) Calculate the volume that the air in the tyre at a final pressure of 3.0 × 10⁵ Pa would occupy at 1.0 × 10⁵ Pa. (b) Hence calculate the volume of atmospheric air that must be pumped in. (c) Calculate the number of strokes needed. (d) In practice the air warms as it is pumped. Explain how the pressure changes after pumping stops and the tyre cools. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '27', NULL, false, NULL, false, NULL, '(a) V = 3.0 × 10⁵ × 2000 ÷ 1.0 × 10⁵ = 6000 cm³. (b) Air to add = 6000 − 2000 = 4000 cm³. (c) Strokes = 4000 ÷ 150 = 26.7, so 27 strokes are needed. (d) As the trapped air cools at constant volume its molecules slow down and hit the walls less hard and less often, so the pressure falls below the value reached while it was warm. Mark scheme (6 marks). C1: p₁V₁ = p₂V₂ for the final air. C1: 6000 cm³. C1: subtract the 2000 cm³ already present. C1: ÷ 150 cm³ per stroke. B1: pressure falls as the air cools. A1: number of strokes = 27.', 6),
('ecb59bb3-2eb0-505a-b2f3-dda77ae12c15', '009eae83-c43b-4fc4-8ee4-339225138993', 'aedaea73-e04d-4a1b-a2c2-8460f1be716e', 'a-level', '20.4', '9702 coursebook 20.4 · Boyle''s law', 50, 50, 'A fixed mass of gas is compressed at constant temperature. A student records: p = 1.0 × 10⁵ Pa, V = 6.00 × 10⁻⁴ m³; p = 2.0 × 10⁵ Pa, V = 3.00 × 10⁻⁴ m³; p = 4.0 × 10⁵ Pa, V = 1.52 × 10⁻⁴ m³; p = 8.0 × 10⁵ Pa, V = 0.78 × 10⁻⁴ m³. (a) Calculate pV for each reading. (b) State and explain whether the gas obeys Boyle''s law over the whole range. (c) Use the first reading to predict the volume at 8.0 × 10⁵ Pa for an ideal gas, and calculate the percentage by which the measured volume exceeds it. Give only the percentage from (c), in %.', NULL, 3, 'numeric'::answer_type, '4', '%', false, NULL, false, NULL, '(a) First reading: 1.0 × 10⁵ × 6.00 × 10⁻⁴ = 60.0 J. Second reading: 2.0 × 10⁵ × 3.00 × 10⁻⁴ = 60.0 J. Third reading: 4.0 × 10⁵ × 1.52 × 10⁻⁴ = 60.8 J. Fourth reading: 8.0 × 10⁵ × 0.78 × 10⁻⁴ = 62.4 J. (b) pV is constant at low pressure but rises at the higher pressures, so the gas departs from Boyle''s law when it is strongly compressed. (c) Ideal volume: 60.0 ÷ 8.0 × 10⁵ = 7.50 × 10⁻⁵ m³. Percentage excess: (0.78 × 10⁻⁴ − 7.50 × 10⁻⁵) ÷ 7.50 × 10⁻⁵ × 100 = 4.0 %. Mark scheme (5 marks). C1: pV values calculated. B1: pV not constant at high pressure. C1: ideal V = 60.0 ÷ 8.0 × 10⁵. C1: percentage difference. A1: percentage excess = 4.0%.', 5)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('7fcdb42e-cbc7-55fa-820f-2ec0f87464da', 'd4ced685-68d6-51cb-8403-fb744a837214', 'the pressure is proportional to the volume', 'A', false, 0),
('a6db3300-f963-570f-836f-de6a4b077377', 'd4ced685-68d6-51cb-8403-fb744a837214', 'the volume is proportional to the temperature', 'B', false, 1),
('3db95846-e8da-5f47-ba3d-5634e55111fd', 'd4ced685-68d6-51cb-8403-fb744a837214', 'the pressure is inversely proportional to the volume', 'C', true, 2),
('dce746a1-2150-5f8a-aa91-cc3aa5451912', 'd4ced685-68d6-51cb-8403-fb744a837214', 'the pressure is proportional to the temperature', 'D', false, 3),
('88725d70-aaf0-5cab-8ae9-1ac1c4a56db2', 'd403c193-fe10-52bd-b823-e20bc037e50b', 'The mass of gas and its temperature', 'A', true, 0),
('313e9df3-c69f-525f-a9ac-572828b509f7', 'd403c193-fe10-52bd-b823-e20bc037e50b', 'The pressure and temperature', 'B', false, 1),
('4a9470e0-957e-5a98-a04a-df0c5f25714d', 'd403c193-fe10-52bd-b823-e20bc037e50b', 'The volume and temperature', 'C', false, 2),
('62ede1d5-4cb0-587a-8e3b-3a15ce9cec34', 'd403c193-fe10-52bd-b823-e20bc037e50b', 'The mass and the pressure', 'D', false, 3),
('d86651ee-c43a-5f92-a100-182004487e2a', 'f0f24d46-eb56-5167-b2af-d4f2b614fa38', 'a curve getting steeper', 'A', false, 0),
('7ef6e5a6-7b3f-5c53-ba80-bf48e60d30b7', 'f0f24d46-eb56-5167-b2af-d4f2b614fa38', 'a horizontal line', 'B', false, 1),
('623cf8d6-c6bd-5d55-933b-94d4fd235bb9', 'f0f24d46-eb56-5167-b2af-d4f2b614fa38', 'a straight line with negative gradient', 'C', false, 2),
('88c7d148-fa7d-5306-b94c-02b075c42510', 'f0f24d46-eb56-5167-b2af-d4f2b614fa38', 'a straight line through the origin', 'D', true, 3),
('96985448-3a21-5700-b281-e44d6b730d7d', '7540c4fc-316b-5a07-8e57-ec103623b112', 'a straight line through the origin', 'A', false, 0),
('34b88247-de1c-5ab7-82ee-294b1eee1780', '7540c4fc-316b-5a07-8e57-ec103623b112', 'a curve (hyperbola) with p decreasing as V increases', 'B', true, 1),
('b3a9920b-d928-519b-9fd2-61e31736e68b', '7540c4fc-316b-5a07-8e57-ec103623b112', 'a straight line rising', 'C', false, 2),
('9722f564-cb0c-5226-8697-5a932d4f87e4', '7540c4fc-316b-5a07-8e57-ec103623b112', 'a horizontal line', 'D', false, 3),
('a40e5886-be70-50fe-b19e-3d922deeea4c', '99eb4a66-df05-5912-a2ba-7bf2883ec5a5', 'To keep the mass of gas constant', 'A', false, 0),
('e656f748-ea74-53a0-8b88-305f4693232b', '99eb4a66-df05-5912-a2ba-7bf2883ec5a5', 'To stop the gauge breaking', 'B', false, 1),
('5c90a901-266b-523a-8c70-e8dbcf5f5279', '99eb4a66-df05-5912-a2ba-7bf2883ec5a5', 'So the gas stays at the same temperature (heat can flow in or out)', 'C', true, 2),
('d21126cb-4284-5e24-98fa-cc1d1d54cbfd', '99eb4a66-df05-5912-a2ba-7bf2883ec5a5', 'To keep the volume constant', 'D', false, 3),
('7dd1c546-6690-5a3a-ad53-b2e7a23ca047', '5454b967-60e3-5b2a-a0bc-d89116dcfa80', 'It halves', 'A', true, 0),
('a7545a20-a65c-5014-8b4f-846b8f5d4138', '5454b967-60e3-5b2a-a0bc-d89116dcfa80', 'It doubles', 'B', false, 1),
('afff3c94-02d6-500f-a87f-65cf41f02b3e', '5454b967-60e3-5b2a-a0bc-d89116dcfa80', 'It quarters', 'C', false, 2),
('019bbca4-2aa0-567a-9ae9-8885db14c3a0', '5454b967-60e3-5b2a-a0bc-d89116dcfa80', 'It stays the same', 'D', false, 3),
('b1840361-e40a-5ca4-b770-21ace98f5637', 'd7b8d017-36fc-5fb0-8c17-7b333113971d', 'Only m³', 'A', false, 0),
('681e4cbb-4f0d-5e21-a15a-59ea5971ad50', 'd7b8d017-36fc-5fb0-8c17-7b333113971d', 'Only cm³', 'B', false, 1),
('f86ab52d-9b60-5135-926d-6d34af1dcf00', 'd7b8d017-36fc-5fb0-8c17-7b333113971d', 'Only litres', 'C', false, 2),
('ae2a6f7e-ff35-51e1-800f-fadf97e18903', 'd7b8d017-36fc-5fb0-8c17-7b333113971d', 'Any volume unit, as long as both volumes use the same unit', 'D', true, 3),
('6e0b890e-3f1d-50b9-983b-714185fe1b33', '4464fc8b-0d76-5b67-9183-ad233b470376', 'The ratio of pressure to volume', 'A', false, 0),
('beedb676-a8c4-5537-bd4f-a92a47c77023', '4464fc8b-0d76-5b67-9183-ad233b470376', 'The product of pressure and volume', 'B', true, 1),
('ec92af80-d4eb-56f9-a3e9-31a2768b590e', '4464fc8b-0d76-5b67-9183-ad233b470376', 'The sum of pressure and volume', 'C', false, 2),
('db05f5be-e995-5bc2-b9f7-f63434c6a6b9', '4464fc8b-0d76-5b67-9183-ad233b470376', 'The pressure only', 'D', false, 3),
('11d1bfa5-0815-563e-a92c-a9589c9cace9', '4710e8a2-b834-5055-bb4f-eaca270816a0', 'The molecules move faster', 'A', false, 0),
